import math


def standardize_columns(data):
    result = {}
    for key, values in data.items():
        values = list(values)
        n = len(values)
        present = [float(v) for v in values if v is not None]
        if n == 0:
            result[key] = []
            continue
        if not present:
            result[key] = [0.0] * n
            continue
        fill = math.fsum(present) / len(present)
        filled = [fill if v is None else float(v) for v in values]
        mean = math.fsum(filled) / n
        var = math.fsum((x - mean) ** 2 for x in filled) / n
        std = math.sqrt(var)
        if std == 0 or not math.isfinite(std):
            result[key] = [0.0] * n
        else:
            result[key] = [float((x - mean) / std) for x in filled]
    return result

