def salary_histogram(salaries_by_dept, dept):
    values = [float(v) for v in salaries_by_dept[dept]]
    nbins = 10
    if values:
        lo = min(values)
        hi = max(values)
    else:
        lo, hi = 0.0, 1.0
    if lo == hi:
        lo -= 0.5
        hi += 0.5
    width = hi - lo
    step = width / nbins
    edges = [lo + i * step for i in range(nbins)] + [hi]
    edges = [float(e) for e in edges]
    counts = [0] * nbins
    for x in values:
        idx = int((x - lo) / width * nbins)
        if idx >= nbins:
            idx = nbins - 1
        if idx < 0:
            idx = 0
        while idx > 0 and x < edges[idx]:
            idx -= 1
        while idx < nbins - 1 and x >= edges[idx + 1]:
            idx += 1
        counts[idx] += 1
    return counts, edges

