def salary_histogram(salaries_by_dept, dept):
    if dept not in salaries_by_dept:
        raise KeyError(f"Unknown department: {dept!r}")
    data = np.asarray(list(salaries_by_dept[dept]), dtype=float)
    if data.size and not np.all(np.isfinite(data)):
        raise ValueError("Salaries must be finite numbers")
    counts, edges = np.histogram(data, bins=10)
    return [int(c) for c in counts], [float(e) for e in edges]

