import statistics


def _parse_list(text):
    text = (text or '').strip()
    if not text:
        return []
    try:
        value = ast.literal_eval(text)
    except (ValueError, SyntaxError):
        inner = text.strip('[]() ')
        value = [float(p) for p in inner.split(',') if p.strip()]
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        value = [value]
    return list(value)


def summarize_email_lists(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    header = None
    results = []
    for row in reader:
        if not row or all(not c.strip() for c in row):
            continue
        if header is None:
            header = [h.strip().lower() for h in row]
            try:
                ei = header.index('email')
                li = header.index('list')
            except ValueError:
                raise ValueError('CSV must contain email and list columns')
            continue
        email = row[ei].strip() if ei < len(row) else ''
        nums = _parse_list(row[li] if li < len(row) else '')
        total = sum(nums)
        n = len(nums)
        if n == 0:
            mean = float('nan')
            std = float('nan')
        else:
            mean = total / n
            try:
                std = float(statistics.pstdev(nums))
            except Exception:
                std = math.sqrt(sum((x - mean) ** 2 for x in nums) / n)
        results.append((email, total, mean, std))
    return results

import math


def _is_missing(v):
    if v is None:
        return True
    try:
        return isinstance(v, float) and math.isnan(v)
    except TypeError:
        return False


def last_column_skewness(rows):
    if rows is None:
        raise ValueError("table has no rows")
    rows = list(rows)
    if len(rows) == 0:
        raise ValueError("table has no rows")
    ncols = max((len(r) for r in rows), default=0)
    if ncols == 0:
        raise ValueError("table has no columns")
    idx = ncols - 1
    values = []
    for r in rows:
        if len(r) > idx:
            v = r[idx]
            if not _is_missing(v):
                values.append(float(v))
    n = len(values)
    if n == 0:
        raise ValueError("last column has no non-missing values")
    mean = math.fsum(values) / n
    devs = [x - mean for x in values]
    m2 = math.fsum(d * d for d in devs) / n
    m3 = math.fsum(d * d * d for d in devs) / n
    if m2 == 0:
        return float('nan')
    return float(m3 / (m2 ** 1.5))

