def roc_points_and_auc(labels, scores):
    labels = list(labels)
    scores = list(scores)
    if len(labels) != len(scores):
        raise ValueError("labels and scores must have the same length")
    for l in labels:
        if l not in (0, 1):
            raise ValueError("labels must be 0 or 1")
    P = sum(1 for l in labels if l == 1)
    N = len(labels) - P
    if P == 0 or N == 0:
        raise ValueError("labels must contain both classes")
    pairs = sorted(zip(scores, labels), key=lambda x: x[0], reverse=True)
    points = [(0.0, 0.0)]
    tp = 0
    fp = 0
    i = 0
    n = len(pairs)
    while i < n:
        s = pairs[i][0]
        while i < n and pairs[i][0] == s:
            if pairs[i][1] == 1:
                tp += 1
            else:
                fp += 1
            i += 1
        points.append((fp / N, tp / P))
    area = 0.0
    for k in range(1, len(points)):
        x0, y0 = points[k - 1]
        x1, y1 = points[k]
        area += (x1 - x0) * (y0 + y1) / 2.0
    return points, area

import math


def _kernel(sigma):
    radius = int(math.floor(4.0 * sigma + 0.5))
    s2 = sigma * sigma
    w = [math.exp(-0.5 * (x * x) / s2) for x in range(-radius, radius + 1)]
    total = sum(w)
    w = [v / total for v in w]
    return w, radius


def _reflect_index(i, n):
    period = 2 * n
    i %= period
    if i >= n:
        i = period - 1 - i
    return i


def _filter1d(line, weights, radius):
    n = len(line)
    if n == 0:
        return []
    out = []
    w0 = weights[radius]
    for i in range(n):
        acc = w0 * line[i]
        for j in range(1, radius + 1):
            a = line[_reflect_index(i - j, n)]
            b = line[_reflect_index(i + j, n)]
            acc += weights[radius + j] * (a + b)
        out.append(acc)
    return out


def blur_image(image, sigma=2):
    if not isinstance(image, list):
        raise TypeError("image must be a list of rows")
    if isinstance(sigma, bool) or not isinstance(sigma, (int, float)):
        raise TypeError("sigma must be a number")
    if not (sigma > 0) or math.isinf(sigma):
        raise ValueError("sigma must be positive")
    rows = []
    for row in image:
        try:
            rows.append([float(v) for v in row])
        except TypeError:
            raise TypeError("each row must be a sequence of numbers")
    if not rows:
        return []
    width = len(rows[0])
    for r in rows:
        if len(r) != width:
            raise ValueError("all rows must have the same length")
    height = len(rows)
    if width == 0:
        return [[] for _ in range(height)]
    weights, radius = _kernel(float(sigma))
    # filter along axis 0 (columns)
    cols = []
    for c in range(width):
        col = [rows[r][c] for r in range(height)]
        cols.append(_filter1d(col, weights, radius))
    tmp = [[cols[c][r] for c in range(width)] for r in range(height)]
    # filter along axis 1 (rows)
    return [_filter1d(r, weights, radius) for r in tmp]

