from collections import Counter

_BRACKET_RE = re.compile(r'\[[^\[\]]*\]')
_WORD_RE = re.compile(r'\b\w\w+\b')


def _strip_brackets(text):
    prev = None
    while prev != text:
        prev = text
        text = _BRACKET_RE.sub(' ', text)
