import re
from collections import Counter

_TOKEN_RE = re.compile(r"(?u)\b\w\w+\b")


def _strip_brackets(text):
    # Find matched [ ] pairs (handling nesting); unmatched brackets stay literal.
    stack = []
    spans = []
    for i, ch in enumerate(text):
        if ch == '[':
            stack.append(i)
        elif ch == ']' and stack:
            start = stack.pop()
            if not stack:
                spans.append((start, i))
    if not spans:
        return text
    # Remove outermost spans; inner matched spans within an unmatched outer '[' too
    # Collect all matched spans not contained in another matched span
    parts = []
    last = 0
    for s, e in spans:
        parts.append(text[last:s])
        parts.append(' ')
        last = e + 1
    parts.append(text[last:])
    return ''.join(parts)


def _strip_all(text):
    # Repeatedly strip so matched pairs inside an unmatched '[' are also removed.
    prev = None
    while prev != text:
        prev = text
        text = _strip_brackets(text)
        if text == prev:
            # handle matched pairs nested after an unmatched '['
            m = re.search(r"\[[^\[\]]*\]", text)
            if m:
                text = text[:m.start()] + ' ' + text[m.end():]
    return text


def _tokenize(text):
    if text is None:
        return []
    text = _strip_all(str(text))
    return [t.lower() for t in _TOKEN_RE.findall(text)]


def bracket_free_tfidf(texts):
    texts = list(texts)
    n = len(texts)
    counts = [Counter(_tokenize(t)) for t in texts]
    df = Counter()
    for c in counts:
        df.update(c.keys())
    idf = {w: math.log((1 + n) / (1 + d)) + 1.0 for w, d in df.items()}
