_COLUMNS = {'Temperature': 1, 'Humidity': 2, 'Wind Speed': 3, 'Precipitation': 4}


def weather_column_summary(column, data):
    if column not in _COLUMNS:
        raise ValueError('Invalid column: %r' % (column,))
    idx = _COLUMNS[column]
    values = [row[idx] for row in data]
    bins = 10
    if not values:
        return {'sum': 0, 'mean': None, 'min': None, 'max': None, 'histogram': [0] * bins}
    total = sum(values)
    mean = total / len(values)
    lo = min(values)
    hi = max(values)
    first, last = float(lo), float(hi)
    if first == last:
        first -= 0.5
        last += 0.5
    width = (last - first) / bins
    edges = [first + width * i for i in range(bins + 1)]
    edges[-1] = last
    hist = [0] * bins
    for v in values:
        if v == last:
            b = bins - 1
        else:
            b = bisect.bisect_right(edges, v) - 1
            if b < 0:
                b = 0
            elif b >= bins:
                b = bins - 1
        hist[b] += 1
    return {'sum': total, 'mean': mean, 'min': lo, 'max': hi, 'histogram': hist}

