from datetime import datetime


def _to_micro(td):
    return (td.days * 86400 + td.seconds) * 1000000 + td.microseconds


def date_histogram(dates, date_format):
    parsed = []
    for s in dates:
        try:
            parsed.append(datetime.strptime(s, date_format))
        except (TypeError, ValueError) as e:
            raise ValueError("Date %r does not match format %r" % (s, date_format)) from e
    counts = [0] * 10
    if not parsed:
        return counts
    mn = min(parsed)
    mx = max(parsed)
    span = _to_micro(mx - mn)
    if span == 0:
        # Mimic numpy: range expands to (x-0.5, x+0.5), values fall in middle bin
        counts[5] = len(parsed)
        return counts
    for d in parsed:
        off = _to_micro(d - mn)
        idx = (off * 10) // span
        if idx >= 10:
            idx = 9
        counts[idx] += 1
    return counts

