import json
import math


def _quantile(sorted_vals, p):
    n = len(sorted_vals)
    if n == 1:
        return float(sorted_vals[0])
    pos = (n - 1) * p
    lo = int(math.floor(pos))
    hi = min(lo + 1, n - 1)
    frac = pos - lo
    return float(sorted_vals[lo] + (sorted_vals[hi] - sorted_vals[lo]) * frac)


def boxplot_stats_at_path(json_data, key_path):
    try:
        data = json.loads(json_data)
    except (ValueError, TypeError) as e:
        raise ValueError("Malformed JSON: %s" % e)

    current = data
    for key in key_path:
        if isinstance(current, dict):
            if key not in current:
                raise KeyError(key)
            current = current[key]
        elif isinstance(current, list) and isinstance(key, int) and not isinstance(key, bool):
            if -len(current) <= key < len(current):
                current = current[key]
            else:
                raise KeyError(key)
        else:
            raise KeyError(key)

    if not isinstance(current, str):
        raise ValueError("Value at path is not a string")
    if current.strip() == "":
        raise ValueError("Data string is empty")

    values = []
    for token in current.split(","):
        t = token.strip()
        if t == "":
            raise ValueError("Empty value in data string")
        try:
            v = float(t)
        except ValueError:
            raise ValueError("Non-numeric value: %r" % t)
        if math.isnan(v) or math.isinf(v):
            raise ValueError("Non-finite value: %r" % t)
        values.append(v)

    values.sort()
    q1 = _quantile(values, 0.25)
    median = _quantile(values, 0.5)
    q3 = _quantile(values, 0.75)
    iqr = q3 - q1
    low_fence = q1 - 1.5 * iqr
    high_fence = q3 + 1.5 * iqr

    inside = [v for v in values if low_fence <= v <= high_fence]
    outliers = [float(v) for v in values if v < low_fence or v > high_fence]
    if inside:
        whisker_low = float(min(inside))
        whisker_high = float(max(inside))
    else:
        whisker_low = q1
        whisker_high = q3

    return {
        'q1': q1,
        'median': median,
        'q3': q3,
        'whisker_low': whisker_low,
        'whisker_high': whisker_high,
        'outliers': sorted(outliers),
    }

