import csv
import io
import math
from fractions import Fraction


def _parse_value(val):
    if val is None:
        raise ValueError("missing value")
    s = val.strip()
    if not s:
        raise ValueError("missing value")
    try:
        f = float(s)
    except (ValueError, TypeError):
        raise ValueError("non-numeric value: %r" % val)
    if not math.isfinite(f):
        raise ValueError("non-finite value: %r" % val)
    try:
        return Fraction(s)
    except (ValueError, ZeroDivisionError):
        return Fraction(f)


def _read(text):
    reader = csv.reader(io.StringIO(text))
    rows = [r for r in reader if r and any(c.strip() for c in r)]
    if not rows:
        raise ValueError("CSV has no header")
    header = [h.strip() for h in rows[0]]
    data = rows[1:]
    for r in data:
        if len(r) != len(header):
            raise ValueError("row length does not match header")
    return header, data


def predict_linear_regression(train_csv, test_csv, target):
    th, tdata = _read(train_csv)
    sh, sdata = _read(test_csv)
    target = target.strip() if isinstance(target, str) else target
    if target not in th:
        raise ValueError("target column not found")
    features = [h for h in th if h != target]
    tidx = th.index(target)
    fidx_train = [th.index(h) for h in features]
    try:
        fidx_test = [sh.index(h) for h in features]
    except ValueError:
        raise ValueError("test CSV missing feature columns")
    if not tdata:
        raise ValueError("no training rows")

    X = []
    y = []
    for r in tdata:
        X.append([Fraction(1)] + [_parse_value(r[i]) for i in fidx_train])
        y.append(_parse_value(r[tidx]))
    Xt = []
    for r in sdata:
        Xt.append([Fraction(1)] + [_parse_value(r[i]) for i in fidx_test])

    p = len(features) + 1
    # Normal equations augmented matrix
    A = [[Fraction(0)] * (p + 1) for _ in range(p)]
    for xi, yi in zip(X, y):
        for a in range(p):
            xa = xi[a]
            if xa == 0:
                continue
            row = A[a]
            for b in range(p):
                row[b] += xa * xi[b]
            row[p] += xa * yi

    # Reduced row echelon form
    pivots = []
    r = 0
    for c in range(p):
        piv = None
        for i in range(r, p):
            if A[i][c] != 0:
                piv = i
                break
        if piv is None:
            continue
        A[r], A[piv] = A[piv], A[r]
        pv = A[r][c]
        A[r] = [v / pv for v in A[r]]
        for i in range(p):
            if i != r and A[i][c] != 0:
                factor = A[i][c]
                Ar = A[r]
                A[i] = [vi - factor * vr for vi, vr in zip(A[i], Ar)]
        pivots.append((r, c))
        r += 1
        if r == p:
            break

    beta = [Fraction(0)] * p
    for (ri, ci) in pivots:
        beta[ci] = A[ri][p]

    result = []
    for xi in Xt:
        s = sum((a * b for a, b in zip(xi, beta)), Fraction(0))
        result.append(float(s))
    return result

