        if len(r) != len(header):
            raise ValueError(f"{name} has a row with the wrong number of fields")
    return header, data


def _to_float(s):
    t = s.strip()
    if t.lower() in _MISSING:
        raise ValueError(f"missing value: {s!r}")
    try:
        v = float(t)
    except ValueError:
        raise ValueError(f"non-numeric value: {s!r}")
    if not math.isfinite(v):
        raise ValueError(f"non-finite value: {s!r}")
    return v


def _clean(p):
    r = round(p)
    if abs(p - r) <= 1e-9 * max(1.0, abs(p)):
        p = float(r)
    return float(p) + 0.0


def predict_linear_regression(train_csv, test_csv, target):
    train_header, train_rows = _parse_csv(train_csv, "train_csv")
    test_header, test_rows = _parse_csv(test_csv, "test_csv")
    target = str(target).strip()
    if target not in train_header:
        raise ValueError(f"target column {target!r} not found in train_csv")
    if set(test_header) != set(train_header):
        raise ValueError("train_csv and test_csv must have the same columns")
    if not train_rows:
        raise ValueError("train_csv has no data rows")

    features = [c for c in train_header if c != target]
    t_idx = train_header.index(target)
    f_idx_train = [train_header.index(c) for c in features]
    f_idx_test = [test_header.index(c) for c in features]

    X = np.array([[1.0] + [_to_float(r[i]) for i in f_idx_train] for r in train_rows], dtype=float)
    y = np.array([_to_float(r[t_idx]) for r in train_rows], dtype=float)

    Xt = np.array([[1.0] + [_to_float(r[i]) for i in f_idx_test] for r in test_rows], dtype=float)
    if not test_rows:
