import math


def _solve_symmetric_system(a, b):
    n = len(a)
    m = [list(a[i]) + [b[i]] for i in range(n)]
    scale = max((abs(m[i][i]) for i in range(n)), default=0.0)
    tol = scale * 1e-12 * max(n, 1)
    pivot_cols = []
    row = 0
    for col in range(n):
        if row >= n:
            break
        best = max(range(row, n), key=lambda r: abs(m[r][col]))
        if abs(m[best][col]) <= tol:
            continue
        m[row], m[best] = m[best], m[row]
        piv = m[row][col]
        m[row] = [v / piv for v in m[row]]
        for r in range(n):
            if r != row:
                f = m[r][col]
                if f != 0.0:
