    try:
        X = [[Fraction(v) for v in r] for r in rows]
        y = [Fraction(t) for t in targets]
    except (ValueError, OverflowError, TypeError):
        return None
    xm = [sum(X[k][j] for k in range(n)) / n for j in range(p)]
    ym = sum(y) / n
    cols = [[X[k][j] - xm[j] for k in range(n)] for j in range(p)]
    yc = [v - ym for v in y]
    A = [[None] * p for _ in range(p)]
    for i in range(p):
        ci = cols[i]
        for j in range(i, p):
            cj = cols[j]
            s = sum(a * b for a, b in zip(ci, cj))
            A[i][j] = s
            A[j][i] = s
    b = [sum(a * v for a, v in zip(cols[i], yc)) for i in range(p)]
    M = [A[i][:] + [b[i]] for i in range(p)]
    for c in range(p):
        piv = None
        for r in range(c, p):
            if M[r][c] != 0:
                piv = r
                break
        if piv is None:
            return None
        M[c], M[piv] = M[piv], M[c]
        pv = M[c][c]
        for r in range(c + 1, p):
            f = M[r][c]
            if f != 0:
                f = f / pv
                Mr, Mc = M[r], M[c]
                for k in range(c, p + 1):
                    Mr[k] -= f * Mc[k]
    coef = [Fraction(0)] * p
    for i in range(p - 1, -1, -1):
        s = M[i][p] - sum(M[i][k] * coef[k] for k in range(i + 1, p))
        coef[i] = s / M[i][i]
    intercept = ym - sum(m * c for m, c in zip(xm, coef))
    return [float(c) for c in coef], float(intercept)


def _numeric_solve(rows, targets):
    X = np.asarray(rows, dtype=float)
    y = np.asarray(targets, dtype=float)
