    ym = y.mean()
    Xc = X - xm
    yc = y - ym
    scale = np.linalg.norm(Xc, axis=0)
    scale[scale == 0] = 1.0
    coef, *_ = np.linalg.lstsq(Xc / scale, yc, rcond=None)
    coef = coef / scale
    intercept = ym - float(xm @ coef)
    return [float(c) for c in coef], float(intercept)


