from decimal import Decimal, localcontext
import math


def _frac_to_decimal(f):
    return Decimal(f.numerator) / Decimal(f.denominator)


def describe_distribution(sample, bins):
    values = list(sample)
    if isinstance(bins, bool) or not isinstance(bins, int):
        if isinstance(bins, float) and bins.is_integer():
            bins = int(bins)
        else:
            raise ValueError("bins must be a positive integer")
    if bins < 1:
        raise ValueError("bins must be a positive integer")
    for v in values:
        if isinstance(v, float) and not math.isfinite(v):
            raise ValueError("sample values must be finite")
    if len(set(values)) < 2:
        raise ValueError("sample must contain at least two distinct values")

    fr = [Fraction(v) for v in values]
    n = len(fr)
    mean = sum(fr) / n
    devs = [x - mean for x in fr]
    m2 = sum(d * d for d in devs) / n
    m3 = sum(d ** 3 for d in devs) / n
    m4 = sum(d ** 4 for d in devs) / n

    with localcontext() as ctx:
        ctx.prec = 60
        dm2 = _frac_to_decimal(m2)
        dm3 = _frac_to_decimal(m3)
        skew_dec = dm3 / (dm2 * dm2.sqrt())
        skewness = float(skew_dec)

    kurtosis = float(m4 / (m2 * m2) - 3)

    lo = min(fr)
    hi = max(fr)
    span = hi - lo
    counts = [0] * bins
    for x in fr:
        idx = math.floor((x - lo) * bins / span)
        if idx >= bins:
            idx = bins - 1
        if idx < 0:
            idx = 0
        counts[idx] += 1

    return (skewness, kurtosis, counts)

