_VOID = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
    'meta', 'param', 'source', 'track', 'wbr', 'keygen', 'command', 'basefont',
    'bgsound', 'frame', 'isindex'
}

_NON_NESTING = {'p', 'li', 'option', 'dt', 'dd', 'tr', 'td', 'th', 'a', 'optgroup'}

_P_CLOSERS = {
    'address', 'article', 'aside', 'blockquote', 'details', 'div', 'dl',
    'fieldset', 'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3',
    'h4', 'h5', 'h6', 'header', 'hgroup', 'hr', 'main', 'menu', 'nav', 'ol',
    'p', 'pre', 'section', 'table', 'ul'
}


class _FirstTagParser(HTMLParser):
    def __init__(self, target):
        super().__init__(convert_charrefs=True)
        self.target = target.lower()
        self.stack = []
        self.capturing = False
        self.done = False
        self.found = False
        self.target_index = None
        self.parts = []

    def _finish(self):
        self.capturing = False
        self.done = True

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        tag = tag.lower()
        if self.capturing:
            # implicit closing of the target element
            if tag == self.target and tag in _NON_NESTING:
                self._finish()
                return
            if self.target == 'p' and tag in _P_CLOSERS:
                self._finish()
                return
            if tag not in _VOID:
                self.stack.append(tag)
            return
        if tag == self.target:
            self.found = True
            if tag in _VOID:
                self._finish()
                return
            self.stack.append(tag)
            self.target_index = len(self.stack) - 1
            self.capturing = True
            return
        if tag not in _VOID:
            self.stack.append(tag)

    def handle_startendtag(self, tag, attrs):
        if self.done:
            return
        tag = tag.lower()
        if not self.capturing and tag == self.target:
            self.found = True
            self._finish()
            return
        if self.capturing and self.target == 'p' and tag in _P_CLOSERS:
            self._finish()
            return
        # self-closing: nothing pushed

    def handle_endtag(self, tag):
        if self.done:
            return
        tag = tag.lower()
        idx = None
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i] == tag:
                idx = i
                break
        if idx is None:
            return
        del self.stack[idx:]
        if self.capturing and self.target_index is not None and idx <= self.target_index:
            self._finish()

    def handle_data(self, data):
        if self.capturing and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    if html is None or not tag:
        return None
    parser = _FirstTagParser(tag)
    try:
        parser.feed(html)
        parser.close()
    except Exception:
        pass
    if not parser.found:
        return None
    text = ''.join(parser.parts)
    if not text:
        return None
    return text

