from fractions import Fraction
from decimal import Decimal, localcontext


def _to_fraction(x):
    if isinstance(x, Fraction):
        return x
    if isinstance(x, int):
        return Fraction(x)
    try:
        import numbers
        if isinstance(x, numbers.Integral):
            return Fraction(int(x))
    except Exception:
        pass
    f = float(x)
    if not math.isfinite(f):
        raise ValueError("non-finite")
    return Fraction(f)


def _frac_to_dec(fr):
    return Decimal(fr.numerator) / Decimal(fr.denominator)


def _skew_row(row):
    vals = list(row)
    n = len(vals)
    if n == 0:
        return float('nan')
    try:
        xs = [_to_fraction(v) for v in vals]
    except (ValueError, OverflowError, TypeError):
        return float('nan')
    mean = sum(xs, Fraction(0)) / n
    devs = [x - mean for x in xs]
    m2 = sum((d * d for d in devs), Fraction(0)) / n
    m3 = sum((d * d * d for d in devs), Fraction(0)) / n
    if m2 == 0:
        return float('nan')
    with localcontext() as ctx:
        ctx.prec = 80
        d2 = _frac_to_dec(m2)
        d3 = _frac_to_dec(m3)
        res = d3 / (d2 * d2.sqrt())
        return float(res)


