    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    try:
        period = int(period)
    except (TypeError, ValueError):
        raise ValueError('period must be an integer')
    if period < 1:
        raise ValueError('period must be a positive integer')
    vals = [float(v) for v in values]
    n = len(vals)
    if n < 2 * period:
        raise ValueError('series must contain at least two full periods')
    mult = model == 'multiplicative'
    if mult and any(v <= 0 for v in vals):
        raise ValueError('multiplicative model requires strictly positive values')

    trend = [None] * n
    h = period // 2
    if period % 2 == 0:
        for i in range(h, n - h):
            s = 0.5 * vals[i - h] + 0.5 * vals[i + h]
            for j in range(i - h + 1, i + h):
                s += vals[j]
            trend[i] = s / period
    else:
        for i in range(h, n - h):
            s = 0.0
            for j in range(i - h, i + h + 1):
                s += vals[j]
            trend[i] = s / period

    sums = [0.0] * period
    counts = [0] * period
    for i in range(n):
        t = trend[i]
        if t is None:
            continue
        if mult:
            if t == 0:
                raise ValueError('trend is zero; cannot use multiplicative model')
            d = vals[i] / t
        else:
            d = vals[i] - t
        sums[i % period] += d
        counts[i % period] += 1

    avgs = []
    for k in range(period):
        if counts[k]:
            avgs.append(sums[k] / counts[k])
        else:
            avgs.append(1.0 if mult else 0.0)
    mean = sum(avgs) / period
    if mult:
        if mean == 0:
            raise ValueError('cannot normalise seasonal component')
        figure = [a / mean for a in avgs]
    else:
        figure = [a - mean for a in avgs]

    seasonal = [figure[i % period] for i in range(n)]
    resid = [None] * n
    for i in range(n):
        t = trend[i]
        if t is None:
            continue
        if mult:
            denom = t * seasonal[i]
            resid[i] = vals[i] / denom if denom != 0 else None
        else:
            resid[i] = vals[i] - t - seasonal[i]

    return {'trend': trend, 'seasonal': seasonal, 'resid': resid}

