        mins.append(min(col))
        maxs.append(max(col))
    result = []
    for r in rows:
        scaled = []
        for j in range(ncols):
            mn, mx = mins[j], maxs[j]
            if mx == mn:
                scaled.append(0.0)
            else:
                scaled.append((r[j] - mn) / (mx - mn))
        avg = sum(scaled) / len(scaled) if scaled else 0.0
