    return result

import math


def last_column_histogram(rows, bins=20):
    if not rows:
        raise ValueError("rows must not be empty")
    if isinstance(bins, bool) or not isinstance(bins, int) or bins < 1:
        raise ValueError("bins must be a positive integer")
    values = []
    for row in rows:
        if len(row) == 0:
            raise ValueError("rows must not contain empty rows")
        values.append(float(row[-1]))
    for v in values:
        if not math.isfinite(v):
            raise ValueError("values must be finite")
    lo = min(values)
    hi = max(values)
    if lo == hi:
        lo -= 0.5
        hi += 0.5
    width = hi - lo
    edges = [lo + i * width / bins for i in range(bins + 1)]
    edges[0] = lo
    edges[-1] = hi
    counts = [0] * bins
    norm = bins / width
    for x in values:
        idx = int((x - lo) * norm)
        if idx >= bins:
            idx = bins - 1
        if idx < 0:
            idx = 0
        if x < edges[idx] and idx > 0:
            idx -= 1
        if idx != bins - 1 and x >= edges[idx + 1]:
            idx += 1
        counts[idx] += 1
    return counts, [float(e) for e in edges]

