import numpy as np


def last_column_histogram(rows, bins=20):
    """Histogram of the last column of a table.

    Uses `bins` equal-width bins spanning the column's min to max (the last
    bin includes its right edge). Returns (counts, edges) as plain Python
    lists of ints and floats.
    """
    if rows is None or len(rows) == 0:
        raise ValueError("rows must not be empty")
    if isinstance(bins, bool) or not isinstance(bins, (int, np.integer)) or bins < 1:
        raise ValueError("bins must be a positive integer")
    try:
        values = [float(row[-1]) for row in rows]
    except (IndexError, TypeError):
        raise ValueError("every row must be a non-empty sequence of numbers")
    arr = np.asarray(values, dtype=float)
    if not np.all(np.isfinite(arr)):
        raise ValueError("last column contains non-finite values")
    counts, edges = np.histogram(arr, bins=int(bins))
    return [int(c) for c in counts], [float(e) for e in edges]

