import csv
import io
import math


def _parse_int(s):
    t = s.strip()
    if not t or '_' in t:
        return None
    try:
        return int(t)
    except ValueError:
        return None


def _parse_float(s):
    t = s.strip()
    if not t or '_' in t:
        return None
    try:
        return float(t)
    except ValueError:
        return None


def _read_doc(text):
    if not isinstance(text, str):
        raise TypeError("each CSV document must be a string")
    rows = [r for r in csv.reader(io.StringIO(text)) if r and any(c != '' for c in r)]
    if not rows:
        return None, []
    header = [h.strip() for h in rows[0]]
    data = []
    for r in rows[1:]:
        r = list(r) + [''] * (len(header) - len(r))
        data.append({h: r[i] for i, h in enumerate(header)})
    return header, data


def concat_csv_tables(counts, csv_texts):
    if not isinstance(counts, list):
        raise TypeError("counts must be a list")
    total = 0
    for c in counts:
        if isinstance(c, bool) or not isinstance(c, int):
            raise TypeError("counts must contain integers")
        if c < 0:
            raise ValueError("counts must be non-negative")
        total += c
    selected = list(csv_texts)[:total]
    if total == 0 or not selected:
        raise ValueError("no documents selected")

    columns = None
    rows = []
    for text in selected:
        header, data = _read_doc(text)
        if header is None:
            continue
        if columns is None:
            columns = header
        else:
            for h in header:
                if h not in columns:
                    columns.append(h)
        rows.extend(data)

    if columns is None:
        return []

    for r in rows:
        for col in columns:
            r.setdefault(col, '')

    converters = {}
    for col in columns:
        values = [r[col] for r in rows]
        non_empty = [v for v in values if v.strip() != '']
        if not non_empty:
            converters[col] = None
            continue
        has_empty = len(non_empty) != len(values)
        if not has_empty and all(_parse_int(v) is not None for v in non_empty):
            converters[col] = 'int'
        elif all(_parse_float(v) is not None for v in non_empty):
            converters[col] = 'float'
        else:
            converters[col] = None

    result = []
    for r in rows:
        out = {}
        for col in columns:
            v = r[col]
            kind = converters[col]
            if kind == 'int':
                out[col] = _parse_int(v)
            elif kind == 'float':
                f = _parse_float(v)
                out[col] = math.nan if f is None else f
            else:
                out[col] = v
        result.append(out)
    return result

