_TOKEN_RE = re.compile(r"(?u)\b\w\w+\b")


def _tokenize(text):
    return _TOKEN_RE.findall(str(text).lower())


def tfidf_scores_for_question_articles(titles, contents):
    picked = []
    for title, body in zip(titles, contents):
        t = str(title).lower()
        if "how" in t or "what" in t:
            picked.append(body)
