        return {}
    docs = [Counter(_tokenize(b)) for b in picked]
    n = len(docs)
    df = Counter()
    for c in docs:
        df.update(c.keys())
    if not df:
        return {}
    idf = {w: math.log((1.0 + n) / (1.0 + d)) + 1.0 for w, d in df.items()}
    totals = {w: 0.0 for w in df}
    for c in docs:
        vec = {w: cnt * idf[w] for w, cnt in c.items()}
        norm = math.sqrt(sum(v * v for v in vec.values()))
        if norm > 0:
            for w, v in vec.items():
                totals[w] += v / norm
    return {w: totals[w] for w in sorted(totals)}

