        return []

    # Determine numeric columns (by index, to tolerate duplicate names)
    numeric = []
    for i in range(n):
        numeric.append(all(_is_numeric(r[i]) for r in raw_rows))

    rows = []
    for r in raw_rows:
        d = {}
        for i, name in enumerate(header):
            d[name] = _to_number(r[i]) if numeric[i] else r[i]
        rows.append(d)

    rows.sort(key=lambda d: d[sort_by_column])
    return rows

