        mean = sum(fr) / n
        devs = [x - mean for x in fr]
        sq = [d * d for d in devs]
        m2 = sum(sq) / n
        if m2 == 0:
            raise ValueError("excess_kurtosis is undefined when all values are equal")
        m4 = sum(s * s for s in sq) / n
        return float(m4 / (m2 * m2) - 3)

    # Fallback for values that can't be represented exactly (e.g. inf/nan)
    fl = [float(v) for v in vals]
    if all(x == fl[0] for x in fl):
        raise ValueError("excess_kurtosis is undefined when all values are equal")
    mean = math.fsum(fl) / n
    devs = [x - mean for x in fl]
