import math


def random_walk_stats(steps):
    steps = list(steps)
    if len(steps) == 0:
        raise ValueError("steps must not be empty")
    positions = []
    total = 0
    for s in steps:
        total += s
        positions.append(total)
    n = len(positions)
    s1 = sum(positions)
    mean = s1 / n
    if n > 1:
        if all(isinstance(p, int) for p in positions):
            s2 = sum(p * p for p in positions)
            var = (n * s2 - s1 * s1) / (n * (n - 1))
        else:
            var = sum((p - mean) ** 2 for p in positions) / (n - 1)
        std = math.sqrt(max(var, 0.0))
    else:
        std = float('nan')
    xs = sorted(positions)

    def pct(q):
        h = (n - 1) * q
        lo = int(math.floor(h))
        hi = min(lo + 1, n - 1)
        frac = h - lo
        return float(xs[lo] + frac * (xs[hi] - xs[lo]))

    return {
        'count': float(n),
        'mean': float(mean),
        'std': float(std),
        'min': float(xs[0]),
        '5%': pct(0.05),
        '25%': pct(0.25),
        '50%': pct(0.5),
        '75%': pct(0.75),
        '95%': pct(0.95),
        'max': float(xs[-1]),
    }

