import string
import unicodedata


def _clean(text):
    out = []
    for ch in text.lower():
        if ch.isdigit() or ch in string.punctuation or unicodedata.category(ch).startswith('P') or unicodedata.category(ch).startswith('S'):
            continue
        out.append(ch)
    return ''.join(out)


def word_count_matrix(texts, stopwords):
    stop = set(w.lower() for w in stopwords)
    docs = []
    for text in texts:
        words = [w for w in _clean(text).split() if len(w) > 1 and w not in stop]
        docs.append(words)
    vocab = sorted(set(w for words in docs for w in words))
    index = {w: i for i, w in enumerate(vocab)}
    counts = []
    for words in docs:
        row = [0] * len(vocab)
        for w in words:
            row[index[w]] += 1
        counts.append(row)
    return vocab, counts

