def _is_number(x):
    return isinstance(x, numbers.Real) and not isinstance(x, bool)


def _corr_exact(cols, n, ncols):
    fcols = [[Fraction(v) for v in col] for col in cols]
    means = [sum(col) / n for col in fcols]
    devs = [[v - m for v in col] for col, m in zip(fcols, means)]
    var = [sum(d * d for d in dv) for dv in devs]
    corr = [[0.0] * ncols for _ in range(ncols)]
    for i in range(ncols):
        for j in range(i, ncols):
            if var[i] == 0 or var[j] == 0:
                r = float('nan')
            elif i == j:
                r = 1.0
            else:
                cov = sum(a * b for a, b in zip(devs[i], devs[j]))
                r2 = (cov * cov) / (var[i] * var[j])
                r = min(1.0, math.sqrt(r2))
                if cov < 0:
                    r = -r
                elif cov == 0:
                    r = 0.0
            corr[i][j] = r
            corr[j][i] = r
    return corr


def _corr_float(cols, n, ncols):
    fcols = [[float(v) for v in col] for col in cols]
    means = [math.fsum(col) / n for col in fcols]
    devs = [[v - m for v in col] for col, m in zip(fcols, means)]
    var = [math.fsum(d * d for d in dv) for dv in devs]
    corr = [[0.0] * ncols for _ in range(ncols)]
    for i in range(ncols):
        for j in range(i, ncols):
            if not (var[i] > 0 and var[j] > 0) or math.isinf(var[i]) or math.isinf(var[j]):
                r = float('nan')
            elif i == j:
                r = 1.0
            else:
                cov = math.fsum(a * b for a, b in zip(devs[i], devs[j]))
                r = cov / math.sqrt(var[i] * var[j])
                if r == r:
                    r = max(-1.0, min(1.0, r))
            corr[i][j] = r
            corr[j][i] = r
    return corr


def row_averages_and_correlations(data):
    if not isinstance(data, (list, tuple)):
        raise ValueError("data must be a list of rows")
    if len(data) == 0:
        return ([], [])
    ncols = None
    for row in data:
        if not isinstance(row, (list, tuple)):
            raise ValueError("each row must be a list of numbers")
        if ncols is None:
            ncols = len(row)
        elif len(row) != ncols:
            raise ValueError("data is not rectangular")
        for v in row:
            if not _is_number(v):
                raise ValueError("data contains non-numeric values")
    if ncols == 0:
        raise ValueError("rows must not be empty")
    n = len(data)

    averages = []
    for row in data:
        try:
            averages.append(float(sum(Fraction(v) for v in row) / ncols))
        except (ValueError, OverflowError, TypeError):
            averages.append(math.fsum(float(v) for v in row) / ncols)

    cols = [[row[j] for row in data] for j in range(ncols)]
    try:
        corr = _corr_exact(cols, n, ncols)
    except (ValueError, OverflowError, TypeError):
        corr = _corr_float(cols, n, ncols)
    return (averages, corr)

