import math
from collections import Counter


def summarize_distribution(values, bins):
    if not values:
        raise ValueError("values must be non-empty")
    if not isinstance(bins, int) or bins <= 0:
        raise ValueError("bins must be a positive integer")

    n = len(values)
    mean = sum(values) / n

    s = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        median = float(s[mid])
    else:
        median = (s[mid - 1] + s[mid]) / 2

    counts = Counter(values)
    max_count = max(counts.values())
    mode = None
    for v in values:
        if counts[v] == max_count:
            mode = v
            break

    variance = sum((v - mean) ** 2 for v in values) / n
    std_dev = math.sqrt(variance)

    lo = min(values)
    hi = max(values)
    histogram = [0] * bins
    span = hi - lo
    if span == 0:
        histogram[0] = n
    else:
        for v in values:
            idx = int((v - lo) * bins / span)
            if idx >= bins:
                idx = bins - 1
            elif idx < 0:
                idx = 0
            histogram[idx] += 1

    return {
        'mean': mean,
        'median': median,
        'mode': mode,
        'std_dev': std_dev,
        'histogram': histogram,
    }

