def abs_sin_cos_spectrum_stats(range_start, range_end, step):
    if range_start > range_end:
        raise ValueError("range_start must not be greater than range_end")
    if step <= 0:
        raise ValueError("step must be positive")
    xs = []
    i = 0
    while True:
        x = range_start + i * step
        if x >= range_end:
            break
        xs.append(x)
        i += 1
    n = len(xs)
    if n == 0:
        raise ValueError("no sample points in the given range")
    signal = [abs(math.sin(x) - math.cos(x)) for x in xs]
    mags = []
    for k in range(n):
        s = 0j
        for t, v in enumerate(signal):
            s += v * cmath.exp(-2j * math.pi * k * t / n)
        mags.append(abs(s))
    mean = float(sum(mags) / n)
    median = float(statistics.median(mags))
    return (mean, median)

