import math

def _twiddle(m, n):
    # returns exp(-2*pi*i*m/n) with exact values at quarter turns
    m %= n
    if (4 * m) % n == 0:
        q = (4 * m) // n
        return [complex(1, 0), complex(0, -1), complex(-1, 0), complex(0, 1)][q]
    ang = -2.0 * math.pi * m / n
    return complex(math.cos(ang), math.sin(ang))


def spectrum_magnitude_histogram(pairs):
    if not pairs:
        return ([], [])
    values = [v for _, v in pairs]
    n = len(values)
    tw = [_twiddle(m, n) for m in range(n)]
    mags = []
    for k in range(n):
        s = complex(0, 0)
        for j, x in enumerate(values):
            s += x * tw[(k * j) % n]
        mags.append(math.hypot(s.real, s.imag))
    bins = 10
    counts = [0] * bins
    lo = min(mags)
    hi = max(mags)
    if lo == hi:
        lo -= 0.5
        hi += 0.5
    width = hi - lo
    for x in mags:
        idx = int((x - lo) / width * bins)
        if idx >= bins:
            idx = bins - 1
        if idx < 0:
            idx = 0
        # correct for floating-point edge issues
        edge_lo = lo + width * idx / bins
        if x < edge_lo and idx > 0:
            idx -= 1
        elif idx < bins - 1 and x >= lo + width * (idx + 1) / bins:
            idx += 1
        counts[idx] += 1
    return (mags, counts)

