                raise ValueError("bin edges must not be NaN")
        for a, b in zip(edges, edges[1:]):
            if b < a:
                raise ValueError("bin edges must increase monotonically")
        n = len(edges) - 1

    counts = [0] * n
    first, last = edges[0], edges[-1]
    for v in vals:
        if v < first or v > last:
            continue
        if v == last:
            idx = n - 1
        else:
            idx = bisect_right(edges, v) - 1
        if 0 <= idx < n:
            counts[idx] += 1

