import math

def _orient(vx, vy, eps=1e-12):
    if abs(vx) <= eps:
        vx = 0.0
        if vy < 0:
            vy = -vy
    elif vx < 0:
        vx, vy = -vx, -vy
    if abs(vy) <= eps:
        vy = 0.0
    return vx, vy


def pca_project_2d(points):
    pts = [(float(p[0]), float(p[1])) for p in points]
    n = len(pts)
    if n == 0:
        return []
    mx = sum(p[0] for p in pts) / n
    my = sum(p[1] for p in pts) / n
    cen = [(x - mx, y - my) for x, y in pts]
    a = sum(x * x for x, _ in cen)
    b = sum(x * y for x, y in cen)
    c = sum(y * y for _, y in cen)
    scale = max(abs(a), abs(b), abs(c))
    if scale == 0 or abs(b) <= 1e-15 * scale:
        if a >= c:
            vx, vy = 1.0, 0.0
        else:
            vx, vy = 0.0, 1.0
    else:
        half_diff = (a - c) / 2.0
        lam = (a + c) / 2.0 + math.hypot(half_diff, b)
        v1 = (lam - c, b)
        v2 = (b, lam - a)
        if math.hypot(*v1) >= math.hypot(*v2):
            vx, vy = v1
        else:
            vx, vy = v2
        norm = math.hypot(vx, vy)
        vx, vy = vx / norm, vy / norm
    vx, vy = _orient(vx, vy)
    wx, wy = _orient(-vy, vx)
    return [[x * vx + y * vy, x * wx + y * wy] for x, y in cen]

