import fnmatch


def _natural_key(name):
    parts = re.split(r'(\d+)', name)
    key = []
    for i, part in enumerate(parts):
        if i % 2 == 1:
            key.append((1, int(part), ''))
        else:
            key.append((0, 0, part.lower()))
    return (key, name)


def _extract(regex, text):
    results = []
    ngroups = regex.groups
    for m in regex.finditer(text):
        if ngroups == 1:
            g = m.group(1)
            results.append(g if g is not None else '')
        else:
            results.append(m.group(0))
    return results


def extract_matches_from_files(files, name_pattern, value_pattern):
    selected = [name for name in files if fnmatch.fnmatchcase(name, name_pattern)]
    if not selected:
        raise ValueError('No file names match pattern %r' % (name_pattern,))
    regex = re.compile(value_pattern)
    selected.sort(key=_natural_key)
    return [(name, _extract(regex, files[name])) for name in selected]

