def _natural_key(name):
    # re.split with a capturing group alternates: text, digits, text, digits, ...
    # so every position has a consistent type across keys (str at even, int at odd).
    parts = re.split(r'(\d+)', name)
    key = []
    for i, part in enumerate(parts):
        if i % 2:
            key.append(int(part))
        else:
            key.append(part)
    return (key, name)


def extract_matches_from_files(files, name_pattern, value_pattern):
    selected = [name for name in files if fnmatchcase(name, name_pattern)]
    if not selected:
        raise ValueError("No file name matches pattern %r" % (name_pattern,))
    regex = re.compile(value_pattern)
    result = []
    for name in sorted(selected, key=_natural_key):
        content = files[name]
        if content is None:
            content = ''
        matches = [m.group(0) for m in regex.finditer(content)]
        result.append((name, matches))
    return result

