from fractions import Fraction


def _to_frac(v):
    try:
        return Fraction(v)
    except (TypeError, ValueError):
        return Fraction(float(v))


def _solve(M):
    # M is n x (n+1) augmented matrix of Fractions; reduced row echelon, free vars = 0
    n = len(M)
    m = n
    row = 0
    pivots = []
    for col in range(m):
        piv = None
        for r in range(row, n):
            if M[r][col] != 0:
                piv = r
                break
        if piv is None:
            continue
        M[row], M[piv] = M[piv], M[row]
        pv = M[row][col]
        M[row] = [v / pv for v in M[row]]
        for r in range(n):
            if r != row and M[r][col] != 0:
                f = M[r][col]
                M[r] = [a - f * b for a, b in zip(M[r], M[row])]
        pivots.append((row, col))
        row += 1
        if row == n:
            break
    sol = [Fraction(0)] * m
    for r, c in pivots:
        sol[c] = M[r][m]
    return sol


def fit_quadratic(x_data, y_data):
    xs = [_to_frac(v) for v in x_data]
    ys = [_to_frac(v) for v in y_data]
    if len(xs) != len(ys):
        raise ValueError("x_data and y_data must have equal length")
    S = [Fraction(0)] * 5
    T = [Fraction(0)] * 3
    for x, y in zip(xs, ys):
        p = Fraction(1)
        for k in range(5):
            S[k] += p
            if k < 3:
                T[k] += p * y
            p *= x
    # unknowns order: a, b, c (powers 2, 1, 0)
    M = [
        [S[4], S[3], S[2], T[2]],
        [S[3], S[2], S[1], T[1]],
        [S[2], S[1], S[0], T[0]],
    ]
    a, b, c = _solve(M)
    params = [float(a), float(b), float(c)]
    fitted = [float(a * x * x + b * x + c) for x in xs]
    return (params, fitted)

