    # Deterministic farthest-point initialization
    c0 = pts[0]
    far_idx = max(range(n), key=lambda i: d2(pts[i], c0))
    c1 = pts[far_idx]
    if d2(c0, c1) == 0:
        return [0] * n

    centers = [c0, c1]
    labels = None
    for _ in range(300):
        new_labels = [0 if d2(p, centers[0]) <= d2(p, centers[1]) else 1 for p in pts]
        if new_labels == labels:
            break
        labels = new_labels
        new_centers = []
        for c in (0, 1):
            members = [p for p, l in zip(pts, labels) if l == c]
            if members:
                sx = sum(p[0] for p in members) / len(members)
                sy = sum(p[1] for p in members) / len(members)
                new_centers.append((sx, sy))
            else:
                new_centers.append(centers[c])
        centers = new_centers

    if labels[0] != 0:
        labels = [1 - l for l in labels]
    return [int(l) for l in labels]

