def _is_number(v):
    return isinstance(v, Real) and not isinstance(v, bool)


def _pearson(xs, ys):
    pairs = [(float(x), float(y)) for x, y in zip(xs, ys)
             if not (math.isnan(float(x)) or math.isnan(float(y)))]
    n = len(pairs)
    if n < 2:
        return float('nan')
    mx = sum(p[0] for p in pairs) / n
    my = sum(p[1] for p in pairs) / n
    sxx = syy = sxy = 0.0
    for x, y in pairs:
        dx = x - mx
        dy = y - my
        sxx += dx * dx
        syy += dy * dy
        sxy += dx * dy
    div = math.sqrt(sxx * syy)
    if div == 0 or math.isnan(div) or math.isinf(div):
        return float('nan')
    r = sxy / div
    if r > 1.0:
        r = 1.0
    elif r < -1.0:
        r = -1.0
    return r


def correlation_without_column(data, column):
    if not data:
        return None
    cols = []
    for name, values in data.items():
        if name == column:
            continue
        vals = list(values)
        if all(_is_number(v) for v in vals):
            cols.append((name, vals))
    if not cols:
        return None
    result = {name: {} for name, _ in cols}
    for i, (nx, vx) in enumerate(cols):
        for j in range(i, len(cols)):
            ny, vy = cols[j]
            if i == j:
                r = _pearson(vx, vx)
                if not math.isnan(r):
