def matrix_tensor_product(P, T):
    """Contract P (MxN) with T (NxAxB) over N.

    Returns (product, sums) where product is MxAxB and sums is MxA
    (product summed over its last axis).
    """
    P = [list(row) for row in P]
    T = [[list(r) for r in mat] for mat in T]
    N = len(T)
    for row in P:
        if len(row) != N:
            raise ValueError(
                "Row length of P (%d) does not match first dimension of T (%d)"
                % (len(row), N)
            )

    if N > 0:
        A = len(T[0])
        B = len(T[0][0]) if A > 0 else 0
        for mat in T:
            if len(mat) != A:
                raise ValueError("Inconsistent tensor shape in T")
            for r in mat:
                if len(r) != B:
                    raise ValueError("Inconsistent tensor shape in T")
    else:
        A = 0
        B = 0

    product = []
    sums = []
    for row in P:
        acc = [[0] * B for _ in range(A)]
        for n in range(N):
            coeff = row[n]
            if coeff == 0:
                # still keep types consistent; zero contributes nothing
                continue
            mat = T[n]
            for a in range(A):
                acc_a = acc[a]
                t_a = mat[a]
                for b in range(B):
                    acc_a[b] += coeff * t_a[b]
        product.append(acc)
        sums.append([sum(acc[a]) for a in range(A)])

    return product, sums

