from fractions import Fraction


def _to_frac(v):
    if isinstance(v, Fraction):
        return v
    if isinstance(v, bool):
        return Fraction(int(v))
    try:
        return Fraction(v)
    except (TypeError, ValueError):
        return Fraction(float(v))


def _solve(A, b):
    n = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    for col in range(n):
        piv = None
        for r in range(col, n):
            if M[r][col] != 0:
                piv = r
                break
        if piv is None:
            raise ValueError("Design matrix is singular; regression is not identifiable")
        M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        for r in range(n):
            if r != col and M[r][col] != 0:
                f = M[r][col] / pv
                rowc = M[col]
                rowr = M[r]
                for k in range(col, n + 1):
                    rowr[k] -= f * rowc[k]
    return [M[i][n] / M[i][i] for i in range(n)]


def fit_joined_regression(feature_rows, target_rows, features, target):
    features = list(features)
    tmap = {}
    for row in target_rows:
        tmap[row['id']] = row
    X = []
    y = []
    for row in feature_rows:
        rid = row['id']
        if rid not in tmap:
            continue
        X.append([Fraction(1)] + [_to_frac(row[f]) for f in features])
        y.append(_to_frac(tmap[rid][target]))
    if not X:
        raise ValueError("No rows remain after joining on 'id'")
    p = len(features) + 1
    XtX = [[Fraction(0)] * p for _ in range(p)]
    Xty = [Fraction(0)] * p
    for xi, yi in zip(X, y):
        for a in range(p):
            xa = xi[a]
            if xa == 0:
                continue
            Xty[a] += xa * yi
            ra = XtX[a]
            for c in range(a, p):
                ra[c] += xa * xi[c]
    for a in range(p):
        for c in range(a):
            XtX[a][c] = XtX[c][a]
    beta = _solve(XtX, Xty)
    residuals = []
    for xi, yi in zip(X, y):
        pred = sum(b * v for b, v in zip(beta, xi))
        residuals.append(float(yi - pred))
    return {
        'coefficients': [float(b) for b in beta[1:]],
        'intercept': float(beta[0]),
        'residuals': residuals,
    }

