import math


def _anova_f(values, labels):
    groups = {}
    for v, l in zip(values, labels):
        groups.setdefault(l, []).append(float(v))
    n = len(values)
    k = len(groups)
    if n == 0 or k < 2 or n - k <= 0:
        return float('nan')
    grand = math.fsum(float(v) for v in values) / n
    ssb = 0.0
    ssw = 0.0
    for g in groups.values():
        m = math.fsum(g) / len(g)
        ssb += len(g) * (m - grand) ** 2
        ssw += math.fsum((x - m) ** 2 for x in g)
    dfb = k - 1
    dfw = n - k
    msb = ssb / dfb
    msw = ssw / dfw
    if msw == 0:
        if msb > 0:
            return float('inf')
        return float('nan')
    return msb / msw


def _pearson(x, y):
    n = len(x)
    x = [float(v) for v in x]
    y = [float(v) for v in y]
    mx = math.fsum(x) / n
    my = math.fsum(y) / n
    dx = [v - mx for v in x]
    dy = [v - my for v in y]
    sxy = math.fsum(a * b for a, b in zip(dx, dy))
    sxx = math.fsum(a * a for a in dx)
    syy = math.fsum(b * b for b in dy)
    denom = math.sqrt(sxx * syy)
    if denom == 0:
        return float('nan')
    r = sxy / denom
    if r > 1.0:
        r = 1.0
    elif r < -1.0:
        r = -1.0
    return r


def _rnd(v):
    if isinstance(v, float) and math.isnan(v):
        return v
    return round(v, 13)


def select_top_features(features, labels):
    labels = list(labels)
    names_all = list(features.keys())
    scored = []
    for idx, name in enumerate(names_all):
        f = _anova_f(list(features[name]), labels)
        key = f if not math.isnan(f) else float('-inf')
        scored.append((key, idx, name))
    scored.sort(key=lambda t: (-t[0] if t[0] != float('-inf') else float('inf'), t[1]))
    top = scored[:2]
    top.sort(key=lambda t: t[1])
    names = [t[2] for t in top]
    a = list(features[names[0]])
    b = list(features[names[1]])
