_WS = b' \t\n\r\x0b\x0c'


def _skip_ws_comments(data, pos):
    n = len(data)
    while pos < n:
        c = data[pos]
        if c in _WS:
            pos += 1
        elif c == 0x23:  # '#'
            while pos < n and data[pos] not in (0x0A, 0x0D):
                pos += 1
        else:
            break
    return pos


def _read_int(data, pos):
    pos = _skip_ws_comments(data, pos)
    n = len(data)
    start = pos
    while pos < n and data[pos] not in _WS and data[pos] != 0x23:
        pos += 1
    tok = data[start:pos]
    if not tok:
        raise ValueError("unexpected end of data")
    if not all(0x30 <= b <= 0x39 for b in tok):
        raise ValueError("invalid number in PGM data: %r" % (tok,))
    return int(tok), pos


def grayscale_histogram(data):
    if isinstance(data, str):
        raise ValueError("data must be bytes")
    try:
        data = bytes(data)
    except Exception:
        raise ValueError("data must be bytes-like")
    if len(data) < 3:
        raise ValueError("data too short to be a PGM image")
    magic = data[:2]
    if magic not in (b'P5', b'P2'):
        raise ValueError("not a PGM image (bad magic number)")
    if data[2] not in _WS and data[2] != 0x23:
        raise ValueError("invalid PGM header")
    pos = 2
    width, pos = _read_int(data, pos)
    height, pos = _read_int(data, pos)
    maxval, pos = _read_int(data, pos)
    if width <= 0 or height <= 0:
        raise ValueError("invalid image dimensions")
    if maxval < 1 or maxval > 255:
        raise ValueError("unsupported maxval (must be 1-255 for 8-bit)")
    count = width * height
    if magic == b'P5':
        if pos >= len(data):
            raise ValueError("missing pixel data")
        if data[pos] == 0x23:
            # comment directly after maxval; skip to end of line
            while pos < len(data) and data[pos] not in (0x0A, 0x0D):
                pos += 1
            if pos >= len(data):
                raise ValueError("missing pixel data")
        if data[pos] not in _WS:
            raise ValueError("invalid PGM header")
        pos += 1
        raster = data[pos:pos + count]
        if len(raster) < count:
            raise ValueError("truncated pixel data")
        hist = Counter(raster)
        if hist and max(hist) > maxval:
            raise ValueError("pixel value exceeds maxval")
        return dict(hist)
    else:
        hist = Counter()
        for _ in range(count):
            v, pos = _read_int(data, pos)
            if v > maxval:
                raise ValueError("pixel value exceeds maxval")
            hist[v] += 1
        return dict(hist)

