def _histogram(values, bins=20):
    counts = [0] * bins
    if not values:
        return counts
    lo = min(values)
    hi = max(values)
    if lo == hi:
        lo = lo - 0.5
        hi = hi + 0.5
    span = hi - lo
    edges = [lo + i * span / bins for i in range(bins + 1)]
