    step = delta / n
    edges = [i * step + first for i in range(n + 1)]
    edges[-1] = last
    norm = n / delta
    counts = [0] * n
    for v in values:
        x = float(v)
        idx = int(math.floor((x - first) * norm))
        if idx >= n:
            idx = n - 1
        if idx < 0:
            idx = 0
        if x < edges[idx] and idx > 0:
            idx -= 1
        elif idx != n - 1 and x >= edges[idx + 1]:
            idx += 1
        counts[idx] += 1
    return (values, counts)

