from fractions import Fraction
from itertools import combinations


def _orient(a, b, c):
    return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])


def _incircle(a, b, c, d):
    adx, ady = a[0] - d[0], a[1] - d[1]
    bdx, bdy = b[0] - d[0], b[1] - d[1]
    cdx, cdy = c[0] - d[0], c[1] - d[1]
    ad = adx * adx + ady * ady
    bd = bdx * bdx + bdy * bdy
    cd = cdx * cdx + cdy * cdy
    return (adx * (bdy * cd - bd * cdy)
            - ady * (bdx * cd - bd * cdx)
            + ad * (bdx * cdy - bdy * cdx))


def _brute_force(pts):
    P = [(Fraction(x), Fraction(y)) for x, y in pts]
    n = len(P)
    edges = set()
    for i, j, k in combinations(range(n), 3):
        a, b, c = P[i], P[j], P[k]
        o = _orient(a, b, c)
        if o == 0:
            continue
        if o < 0:
            b, c = c, b
        ok = True
        for m in range(n):
            if m in (i, j, k):
                continue
            if _incircle(a, b, c, P[m]) > 0:
                ok = False
                break
        if ok:
            edges.add((i, j))
            edges.add((i, k))
            edges.add((j, k))
    return sorted(edges)


def voronoi_neighbors(points):
    pts = [list(p) for p in points]
    if len(pts) < 3:
        raise ValueError("At least three points are required")
    for p in pts:
        if len(p) != 2:
            raise ValueError("Each point must be an [x, y] pair")
    pts = [(float(p[0]), float(p[1])) for p in pts]
    try:
        import numpy as np
        from scipy.spatial import Delaunay
    except Exception:
        return _brute_force(pts)
    try:
        tri = Delaunay(np.asarray(pts, dtype=float))
    except Exception:
        return _brute_force(pts)
    edges = set()
    for simplex in tri.simplices:
        s = [int(v) for v in simplex]
        for a, b in combinations(s, 2):
            if a > b:
                a, b = b, a
            edges.add((a, b))
    return sorted(edges)

