def _lloyd(pts, centers, max_iter=300):
    centers = [list(c) for c in centers]
    k = len(centers)
    assign = None
    for _ in range(max_iter):
        new_assign = []
        for p in pts:
            best = 0
            bd = _sqdist(p, centers[0])
            for j in range(1, k):
                d = _sqdist(p, centers[j])
                if d < bd:
                    bd = d
                    best = j
            new_assign.append(best)
        if new_assign == assign:
            break
        assign = new_assign
        sums = [[0.0, 0.0, 0] for _ in range(k)]
        for p, a in zip(pts, assign):
            s = sums[a]
            s[0] += p[0]
            s[1] += p[1]
            s[2] += 1
        for j in range(k):
            if sums[j][2] > 0:
                centers[j] = [sums[j][0] / sums[j][2], sums[j][1] / sums[j][2]]
    inertia = 0.0
    for p in pts:
        inertia += min(_sqdist(p, c) for c in centers)
