def _farthest_first(pts, k, start):
    centers = [pts[start]]
    dists = [_sqdist(p, pts[start]) for p in pts]
    while len(centers) < k:
        idx = max(range(len(pts)), key=lambda i: dists[i])
        c = pts[idx]
        centers.append(c)
        for i, p in enumerate(pts):
            d = _sqdist(p, c)
