    while len(centers) < k:
        total = sum(dists)
        if total <= 0:
            idx = rng.randrange(n)
        else:
            r = rng.random() * total
            acc = 0.0
            idx = n - 1
            for i, d in enumerate(dists):
                acc += d
                if acc >= r:
                    idx = i
                    break
        c = pts[idx]
        centers.append(c)
        for i, p in enumerate(pts):
