def xml_to_dict(s):
    if s is None:
        raise ValueError("Input is empty")
    if isinstance(s, (bytes, bytearray)):
        if not bytes(s).strip():
            raise ValueError("Input is empty")
    elif isinstance(s, str):
        if not s.strip():
            raise ValueError("Input is empty")
    else:
        raise ValueError("Input must be a string")

    stack = []
    result = {}

    def add_child(container, key, value):
        if key in container:
            existing = container[key]
            if isinstance(existing, list):
                existing.append(value)
            else:
                container[key] = [existing, value]
        else:
            container[key] = value

    def start(name, attrs):
        stack.append([name, attrs, {}, []])

    def chars(data):
        if stack:
            stack[-1][3].append(data)

    def end(name):
        tag, attrs, children, data = stack.pop()
        text = ''.join(data).strip()
        if not attrs and not children:
            value = text if text else None
        else:
            value = {}
            for k, v in attrs.items():
                value['@' + k] = v
            for k, v in children.items():
                value[k] = v
            if text:
                value['#text'] = text
        if stack:
            add_child(stack[-1][2], tag, value)
        else:
            result[tag] = value

    parser = _expat.ParserCreate()
    parser.buffer_text = True
    parser.StartElementHandler = start
    parser.EndElementHandler = end
    parser.CharacterDataHandler = chars
    try:
        parser.Parse(s, True)
    except _expat.ExpatError as e:
        raise ValueError("Invalid XML: %s" % e)
    if not result:
        raise ValueError("No root element found")
    return result

