def _quantile(sorted_vals, p):
    n = len(sorted_vals)
    if n == 1:
        return float(sorted_vals[0])
    pos = (n - 1) * p
    lo = int(math.floor(pos))
    hi = min(lo + 1, n - 1)
    frac = pos - lo
    a = sorted_vals[lo]
    b = sorted_vals[hi]
    if frac == 0:
        return float(a)
    return float(a + (b - a) * frac)


def _median(sorted_vals):
    n = len(sorted_vals)
    mid = n // 2
    if n % 2 == 1:
        return float(sorted_vals[mid])
    return (sorted_vals[mid - 1] + sorted_vals[mid]) / 2.0


