class _LinkExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.results = []
        self._current = None  # [index, list_of_text_parts]
        self._skip_depth = 0

    def _finish(self):
        if self._current is not None:
            idx, parts = self._current
            text, href = self.results[idx]
            self.results[idx] = (''.join(parts), href)
            self._current = None

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag == 'a':
            # Nested <a> is invalid; browsers implicitly close the open one.
            self._finish()
            href = None
            found = False
            for name, value in attrs:
                if name.lower() == 'href' and not found:
                    href = value if value is not None else ''
                    found = True
            self.results.append(('', href))
            self._current = [len(self.results) - 1, []]
        elif tag in ('script', 'style'):
            self._skip_depth += 1

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag == 'a':
            self._finish()
        elif tag in ('script', 'style'):
            if self._skip_depth > 0:
                self._skip_depth -= 1

    def handle_data(self, data):
        if self._current is not None and self._skip_depth == 0:
            self._current[1].append(data)

    def close(self):
        super().close()
        self._finish()


def extract_links(html):
    if not html:
        return []
    parser = _LinkExtractor()
    parser.feed(html)
    parser.close()
    return list(parser.results)

