from collections import Counter


def word_length_stats(words, letter):
    """Return the mean, median and mode of the lengths of the words that start with `letter`.

    The match is case-sensitive. If several lengths tie for the mode, the smallest
    is returned. If no words match, every statistic is None.
    """
    lengths = sorted(len(w) for w in words if isinstance(w, str) and w.startswith(letter))
    n = len(lengths)
    if n == 0:
        return {'mean': None, 'median': None, 'mode': None}

    mean = sum(lengths) / n

    mid = n // 2
    if n % 2 == 1:
        median = float(lengths[mid])
    else:
        median = (lengths[mid - 1] + lengths[mid]) / 2.0

    counts = Counter(lengths)
    max_count = max(counts.values())
    mode = min(length for length, c in counts.items() if c == max_count)

    return {'mean': mean, 'median': median, 'mode': mode}

