def zscore_normalize_columns(matrix):
    rows = [list(r) for r in matrix]
    n = len(rows)
    if n == 0:
        return []
    m = len(rows[0])
    for r in rows:
        if len(r) != m:
            raise ValueError("All rows must have the same length")
    result = [[0.0] * m for _ in range(n)]
    for j in range(m):
        col = [float(rows[i][j]) for i in range(n)]
        first = col[0]
        if all(v == first for v in col):
            continue
        mean = math.fsum(col) / n
        var = math.fsum((v - mean) ** 2 for v in col) / n
        std = math.sqrt(var)
        if std == 0.0 or not math.isfinite(std):
            if std == 0.0:
                continue
        for i in range(n):
            result[i][j] = (col[i] - mean) / std
    return result

