import math


def histogram_with_normal_fit(data, bins):
    values = [float(x) for x in data]
    if isinstance(bins, bool) or not isinstance(bins, int) or bins < 1:
        raise ValueError("bins must be a positive integer")
    if len(set(values)) < 2:
        raise ValueError("data must contain at least two distinct values")
    for v in values:
        if math.isnan(v) or math.isinf(v):
            raise ValueError("data must contain finite numbers")
    n = len(values)
    lo = min(values)
    hi = max(values)
    width = (hi - lo) / bins
    edges = [lo + i * width for i in range(bins)] + [hi]
    counts = [0] * bins
    for x in values:
        idx = int((x - lo) / width)
        if idx < 0:
            idx = 0
        if idx > bins - 1:
            idx = bins - 1
        while idx > 0 and x < edges[idx]:
            idx -= 1
        while idx < bins - 1 and x >= edges[idx + 1]:
            idx += 1
        counts[idx] += 1
    mean = math.fsum(values) / n
    var = math.fsum((x - mean) ** 2 for x in values) / n
    std = math.sqrt(var)
    norm = 1.0 / (std * math.sqrt(2.0 * math.pi))
    rows = []
    for i in range(bins):
        center = lo + (i + 0.5) * width
        density = counts[i] / (n * width)
        z = (center - mean) / std
        pdf = norm * math.exp(-0.5 * z * z)
        rows.append((center, density, pdf))
    return (mean, std, rows)

