try:
    from zoneinfo import ZoneInfo
except ImportError:  # pragma: no cover
    ZoneInfo = None


def _get_tz(name):
    if ZoneInfo is not None:
        try:
            return ZoneInfo(name)
        except Exception:
            pass
    try:
        from dateutil import tz as _dtz
        z = _dtz.gettz(name)
        if z is not None:
            return z
    except ImportError:
        pass
    if name.upper() in ('UTC', 'Z', 'GMT', 'ETC/UTC'):
        return timezone.utc
    raise ValueError('Unknown timezone: %r' % (name,))


def convert_timezone(date_str, from_tz, to_tz):
    fmt = '%Y-%m-%d %H:%M:%S'
    naive = datetime.strptime(date_str.strip(), fmt)
    src = _get_tz(from_tz)
    dst = _get_tz(to_tz)
    aware = naive.replace(tzinfo=src)
    converted = aware.astimezone(timezone.utc).astimezone(dst)
    return converted.strftime(fmt)

