    pts = [(float(p[0]), float(p[1])) for p in points]
    n = len(pts)
    if n == 0 or k <= 0:
        return []
    k = min(k, n)

    def d2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def init_from(start):
        cents = [pts[start]]
        mind = [d2(p, pts[start]) for p in pts]
        while len(cents) < k:
            best_i = max(range(n), key=lambda i: mind[i])
            c = pts[best_i]
            cents.append(c)
            for i in range(n):
                dd = d2(pts[i], c)
                if dd < mind[i]:
                    mind[i] = dd
        return cents

    def lloyd(cents):
        cents = list(cents)
        assign = None
        for _ in range(500):
            new_assign = []
            for p in pts:
                bi = 0
                bd = d2(p, cents[0])
                for j in range(1, k):
                    dd = d2(p, cents[j])
                    if dd < bd:
                        bd = dd
                        bi = j
                new_assign.append(bi)
            if new_assign == assign:
                break
            assign = new_assign
            new_cents = []
            for j in range(k):
                members = [pts[i] for i in range(n) if assign[i] == j]
                if members:
                    sx = sum(m[0] for m in members)
                    sy = sum(m[1] for m in members)
                    new_cents.append((sx / len(members), sy / len(members)))
                else:
                    new_cents.append(cents[j])
            cents = new_cents
        sse = sum(d2(pts[i], cents[assign[i]]) for i in range(n))
        return sse, cents

    best = None
    starts = list(range(min(n, 10)))
    # also try starting from point closest to the overall mean
    mx = sum(p[0] for p in pts) / n
    my = sum(p[1] for p in pts) / n
