def _sqdist(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def _init_pp(pts, k, rng):
    n = len(pts)
    centers = [pts[rng.randrange(n)]]
    while len(centers) < k:
        d = [min(_sqdist(p, c) for c in centers) for p in pts]
        total = math.fsum(d)
        if total <= 0:
            centers.append(pts[rng.randrange(n)])
            continue
        r = rng.random() * total
        cum = 0.0
        pick = None
        for i, di in enumerate(d):
            cum += di
            if di > 0 and cum >= r:
                pick = i
                break
        if pick is None:
            pick = max(range(n), key=lambda i: d[i])
        centers.append(pts[pick])
    return [tuple(c) for c in centers]


def _lloyd(pts, centers, k, max_iter=300):
    assign = None
    for _ in range(max_iter):
        new_assign = []
        for p in pts:
            best = 0
            bd = _sqdist(p, centers[0])
            for j in range(1, k):
                d = _sqdist(p, centers[j])
                if d < bd:
                    bd = d
                    best = j
            new_assign.append(best)
        if new_assign == assign:
            break
        assign = new_assign
        xs = [[] for _ in range(k)]
        ys = [[] for _ in range(k)]
        for p, a in zip(pts, assign):
            xs[a].append(p[0])
            ys[a].append(p[1])
        new_centers = []
        for j in range(k):
            if xs[j]:
                cnt = len(xs[j])
                new_centers.append((math.fsum(xs[j]) / cnt, math.fsum(ys[j]) / cnt))
            else:
                new_centers.append(centers[j])
        centers = new_centers
    inertia = math.fsum(_sqdist(p, centers[a]) for p, a in zip(pts, assign))
    return centers, inertia


