    if lo == hi:
        lo -= 0.5
        hi += 0.5
    span = hi - lo
    step = span / bins
    edges = [lo + i * step for i in range(bins)] + [hi]
    counts = [0] * bins
    for x in data:
        idx = int((x - lo) * bins / span)
        if idx < 0:
