import hashlib


def _egcd_inv(a, m):
    a %= m
    if m == 1:
        return 0
    old_r, r = a, m
    old_s, s = 1, 0
    while r != 0:
        qt = old_r // r
        old_r, r = r, old_r - qt * r
        old_s, s = s, old_s - qt * s
    if old_r != 1:
        raise ValueError("e is not invertible modulo phi")
    return old_s % m


def _gcd(a, b):
    while b:
        a, b = b, a % b
    return a


