def dbscan_cluster_labels(points):
    eps_sq = 3 * 3
    min_samples = 2
    n = len(points)
    if n == 0:
        return []

    def dist_sq(a, b):
        return sum((x - y) * (x - y) for x, y in zip(a, b))

    neighbors = []
    for i in range(n):
        nb = [j for j in range(n) if dist_sq(points[i], points[j]) <= eps_sq]
        neighbors.append(nb)
    is_core = [len(neighbors[i]) >= min_samples for i in range(n)]

    labels = [-1] * n
    cluster_id = 0
    for i in range(n):
        if labels[i] != -1 or not is_core[i]:
            continue
        labels[i] = cluster_id
        stack = [i]
        while stack:
            p = stack.pop()
            if not is_core[p]:
                continue
            for q in neighbors[p]:
                if labels[q] == -1:
                    labels[q] = cluster_id
                    if is_core[q]:
                        stack.append(q)
        cluster_id += 1
    return labels

