import math


def _pearson(xs, ys):
    n = len(xs)
    if n < 2:
        return None
    # Constant columns have undefined correlation
    if all(v == xs[0] for v in xs) or all(v == ys[0] for v in ys):
        return None
    mx = math.fsum(xs) / n
    my = math.fsum(ys) / n
    dx = [x - mx for x in xs]
    dy = [y - my for y in ys]
    sxx = math.fsum(d * d for d in dx)
    syy = math.fsum(d * d for d in dy)
    if sxx <= 0 or syy <= 0:
        return None
    sxy = math.fsum(a * b for a, b in zip(dx, dy))
    r = sxy / (math.sqrt(sxx) * math.sqrt(syy))
    if math.isnan(r):
