import math
import random


def _sqdist(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b))


def _lloyd(points, centers, max_iter=300):
    k = len(centers)
    centers = [list(c) for c in centers]
    labels = None
    for _ in range(max_iter):
        new_labels = []
        for p in points:
            best = 0
            bd = _sqdist(p, centers[0])
            for j in range(1, k):
                d = _sqdist(p, centers[j])
                if d < bd:
                    bd = d
                    best = j
            new_labels.append(best)
        if new_labels == labels:
            break
        labels = new_labels
        dim = len(points[0])
        sums = [[0.0] * dim for _ in range(k)]
        counts = [0] * k
        for p, l in zip(points, labels):
            counts[l] += 1
            s = sums[l]
            for i in range(dim):
                s[i] += p[i]
        for j in range(k):
            if counts[j]:
                centers[j] = [v / counts[j] for v in sums[j]]
    inertia = sum(_sqdist(p, centers[l]) for p, l in zip(points, labels))
    return labels, inertia


def _farthest_init(points, k):
    centers = [points[0]]
    while len(centers) < k:
        best_i, best_d = None, -1.0
        for i, p in enumerate(points):
            d = min(_sqdist(p, c) for c in centers)
            if d > best_d:
                best_d, best_i = d, i
        if best_d <= 0:
            break
        centers.append(points[best_i])
    return centers


def _kpp_init(points, k, rng):
    centers = [points[rng.randrange(len(points))]]
    while len(centers) < k:
        dists = [min(_sqdist(p, c) for c in centers) for p in points]
        total = sum(dists)
        if total <= 0:
            break
        r = rng.random() * total
        acc = 0.0
        chosen = len(points) - 1
        for i, d in enumerate(dists):
            acc += d
            if acc >= r and d > 0:
                chosen = i
                break
        centers.append(points[chosen])
    return centers


def cluster_labels(rows):
    if not rows:
        return []
    n = len(rows)
    dim = len(rows[0])
    if dim == 0:
        return [0] * n
    cols = []
    for j in range(dim):
        vals = [float(r[j]) for r in rows]
        mean = sum(vals) / n
        var = sum((v - mean) ** 2 for v in vals) / n
        std = math.sqrt(var)
        if std > 0:
            cols.append([(v - mean) / std for v in vals])
        else:
            cols.append([0.0] * n)
    points = [[cols[j][i] for j in range(dim)] for i in range(n)]
    distinct = []
    for p in points:
        if p not in distinct:
            distinct.append(p)
            if len(distinct) >= 3:
                break
    k = min(3, len(distinct))
    if k <= 1:
        return [0] * n
    best_labels, best_inertia = None, None
    inits = [_farthest_init(points, k)]
    rng = random.Random(0)
    for _ in range(10):
        inits.append(_kpp_init(points, k, rng))
    for init in inits:
        if len(init) < k:
            continue
        labels, inertia = _lloyd(points, init)
        if best_inertia is None or inertia < best_inertia - 1e-12:
            best_labels, best_inertia = labels, inertia
    if best_labels is None:
        best_labels, _ = _lloyd(points, inits[0])
    mapping = {}
    result = []
    for l in best_labels:
        if l not in mapping:
            mapping[l] = len(mapping)
        result.append(mapping[l])
    return result

from fractions import Fraction


def _solve_exact(A, b):
    # Solve A x = b exactly (A symmetric PSD from normal equations).
    # Rank-deficient case: free variables are set to 0.
    p = len(A)
    M = [row[:] + [b[i]] for i, row in enumerate(A)]
    pivot_cols = []
    r = 0
    for c in range(p):
        if r >= p:
            break
        piv = None
        for i in range(r, p):
            if M[i][c] != 0:
                piv = i
                break
        if piv is None:
            continue
        M[r], M[piv] = M[piv], M[r]
        pv = M[r][c]
        M[r] = [v / pv for v in M[r]]
        for i in range(p):
            if i != r and M[i][c] != 0:
                f = M[i][c]
                Mr = M[r]
                M[i] = [a - f * bb for a, bb in zip(M[i], Mr)]
        pivot_cols.append(c)
        r += 1
    x = [Fraction(0)] * p
    for i, c in enumerate(pivot_cols):
        x[c] = M[i][p]
    return x


def fit_linear_regression(features, values):
    n = len(features)
    if n == 0 or n != len(values):
        raise ValueError("features and values must be non-empty and of equal length")
    p = len(features[0])
    for row in features:
        if len(row) != p:
            raise ValueError("all feature rows must have the same length")
    X = [[Fraction(v) for v in row] for row in features]
    y = [Fraction(v) for v in values]
    nf = Fraction(n)
    xmean = [sum(X[i][j] for i in range(n)) / nf for j in range(p)]
    ymean = sum(y) / nf
    Xc = [[X[i][j] - xmean[j] for j in range(p)] for i in range(n)]
    yc = [y[i] - ymean for i in range(n)]
    A = [[Fraction(0)] * p for _ in range(p)]
    b = [Fraction(0)] * p
    for i in range(n):
        row = Xc[i]
        yi = yc[i]
        for j in range(p):
            rj = row[j]
            if rj == 0:
                continue
            b[j] += rj * yi
            Aj = A[j]
            for k in range(j, p):
                Aj[k] += rj * row[k]
    for j in range(p):
        for k in range(j):
            A[j][k] = A[k][j]
    coefs = _solve_exact(A, b) if p > 0 else []
    intercept = ymean - sum(c * m for c, m in zip(coefs, xmean))
    return {'coefficients': [float(c) for c in coefs], 'intercept': float(intercept)}

