import numpy as np


def _clean(x):
    x = float(x)
    r = round(x, 10)
    if r == 0:
        r = 0.0
    return float(r)


def fit_linear_regression(features, values):
    y = np.asarray(values, dtype=float).ravel()
    n = y.shape[0]
    if n == 0:
        raise ValueError("No data provided")
    X = np.asarray(features, dtype=float)
    if X.size == 0:
        X = X.reshape(n, 0)
    elif X.ndim == 1:
        X = X.reshape(n, -1)
    if X.shape[0] != n:
        raise ValueError("features and values must have the same number of rows")
    p = X.shape[1]
    y_mean = y.mean()
    if p == 0:
        return {'coefficients': [], 'intercept': _clean(y_mean)}
    x_mean = X.mean(axis=0)
    Xc = X - x_mean
    yc = y - y_mean
    coef, _, _, _ = np.linalg.lstsq(Xc, yc, rcond=None)
    intercept = y_mean - float(np.dot(x_mean, coef))
    return {
        'coefficients': [_clean(c) for c in coef],
        'intercept': _clean(intercept),
    }

