import math
from fractions import Fraction


def _is_missing(v):
    if v is None:
        return True
    try:
        return math.isnan(v)
    except TypeError:
        return False


def _pair_corr(xs, ys):
    pairs = [(x, y) for x, y in zip(xs, ys) if not _is_missing(x) and not _is_missing(y)]
    n = len(pairs)
    if n < 2:
        return float('nan')
    try:
        fx = [Fraction(x) for x, _ in pairs]
        fy = [Fraction(y) for _, y in pairs]
    except (ValueError, OverflowError, TypeError):
        fx = fy = None
    if fx is not None:
        mx = sum(fx) / n
        my = sum(fy) / n
        dx = [a - mx for a in fx]
        dy = [b - my for b in fy]
        sxy = sum(a * b for a, b in zip(dx, dy))
        sxx = sum(a * a for a in dx)
        syy = sum(b * b for b in dy)
        if sxx == 0 or syy == 0:
            return float('nan')
        r2 = (sxy * sxy) / (sxx * syy)
        r = math.sqrt(float(r2))
        if r > 1.0:
            r = 1.0
        return r if sxy >= 0 else -r
    # float fallback (e.g. infinities)
    xf = [float(x) for x, _ in pairs]
    yf = [float(y) for _, y in pairs]
    mx = math.fsum(xf) / n
    my = math.fsum(yf) / n
    dx = [a - mx for a in xf]
    dy = [b - my for b in yf]
    sxy = math.fsum(a * b for a, b in zip(dx, dy))
    sxx = math.fsum(a * a for a in dx)
    syy = math.fsum(b * b for b in dy)
    den = math.sqrt(sxx * syy) if sxx >= 0 and syy >= 0 else float('nan')
    if not den or math.isnan(den):
        return float('nan')
    r = sxy / den
    return max(-1.0, min(1.0, r))


def column_correlation_matrix(data, cols):
    k = len(cols)
    columns = [[row[i] if i < len(row) else None for row in data] for i in range(k)]
    result = [[float('nan')] * k for _ in range(k)]
    for i in range(k):
        for j in range(i, k):
            r = _pair_corr(columns[i], columns[j])
            if i == j and not math.isnan(r):
                r = 1.0
            result[i][j] = r
            result[j][i] = r
    return result

import math


def _dot(a, b):
    return math.fsum(x * y for x, y in zip(a, b))


def linear_regression_r2(data, target):
    y = [float(v) for v in data[target]]
    n = len(y)
    if n == 0:
        return 0.0
    y_mean = math.fsum(y) / n
    yc = [v - y_mean for v in y]
    ss_tot = _dot(yc, yc)

    # Centered feature columns (centering accounts for the intercept)
    feats = []
    for name, col in data.items():
        if name == target:
            continue
        col = [float(v) for v in col]
        m = math.fsum(col) / n
        feats.append([v - m for v in col])

    # Modified Gram-Schmidt with reorthogonalization and rank-deficiency handling
    basis = []
    for f in feats:
        orig_norm2 = _dot(f, f)
        if orig_norm2 == 0.0:
            continue
        v = list(f)
        for _ in range(2):
            for b, bb in basis:
                c = _dot(v, b) / bb
                if c != 0.0:
                    v = [vi - c * bi for vi, bi in zip(v, b)]
        vv = _dot(v, v)
        if vv <= 1e-20 * orig_norm2 or vv == 0.0:
            continue
        basis.append((v, vv))

    # Project centered y onto the column space; residual is what's left
    r = list(yc)
    for _ in range(2):
        for b, bb in basis:
            c = _dot(r, b) / bb
            if c != 0.0:
                r = [ri - c * bi for ri, bi in zip(r, b)]
    ss_res = _dot(r, r)

    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0
    return float(1.0 - ss_res / ss_tot)

