def linear_regression_r2(data, target):
    if target not in data:
        raise KeyError(target)
    y = np.asarray(data[target], dtype=float)
    n = y.shape[0]
    feature_names = [k for k in data if k != target]
    if feature_names:
        X = np.column_stack([np.asarray(data[k], dtype=float) for k in feature_names])
    else:
        X = np.empty((n, 0), dtype=float)
    if n == 0:
        raise ValueError("empty data")

