class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found = False
        self.done = False
        self.depth = 0
        self.rows = []
        self.row = None
        self.cell = None

    def _close_cell(self):
        if self.cell is not None:
            if self.row is None:
                self.row = []
                self.rows.append(self.row)
            self.row.append(''.join(self.cell))
            self.cell = None

    def _close_row(self):
        self._close_cell()
        self.row = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return
        tag = tag.lower()
        if not self.found:
            if tag == 'table':
                cls = None
                for name, value in attrs:
                    if name == 'class':
                        cls = value
                        break
                if cls == 'data-table':
                    self.found = True
                    self.depth = 1
            return
        if tag == 'table':
            self.depth += 1
            return
        if self.depth == 1:
            if tag == 'tr':
                self._close_row()
                self.row = []
                self.rows.append(self.row)
            elif tag in ('td', 'th'):
                self._close_cell()
                if self.row is None:
                    self.row = []
                    self.rows.append(self.row)
                if tag == 'td':
                    self.cell = []
            elif tag in ('thead', 'tbody', 'tfoot'):
                self._close_row()

    def handle_endtag(self, tag):
        if not self.found or self.done:
            return
        tag = tag.lower()
        if tag == 'table':
            self.depth -= 1
            if self.depth == 0:
                self._close_row()
                self.done = True
            return
        if self.depth == 1:
            if tag == 'td':
                self._close_cell()
            elif tag == 'tr':
                self._close_row()
            elif tag in ('thead', 'tbody', 'tfoot'):
                self._close_row()

    def handle_data(self, data):
        if self.found and not self.done and self.cell is not None:
            self.cell.append(data)


def extract_data_table_rows(html):
    if not html:
        return []
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    if not parser.found:
        return []
    if not parser.done:
        parser._close_row()
    return parser.rows

