def min_max_scale_columns(rows):
    """Min-max scale each column of a rectangular table independently.

    Each column's minimum maps to 0.0 and its maximum to 1.0. A constant
    column (where min == max) maps to 0.0 everywhere, avoiding division by
    zero. Returns a new table; the input is not modified.
    """
    rows = [list(r) for r in rows]
    if not rows:
        return []
    n_cols = len(rows[0])
    for r in rows:
        if len(r) != n_cols:
            raise ValueError("all rows must have the same number of columns")
    if n_cols == 0:
        return [[] for _ in rows]

    mins = [min(r[c] for r in rows) for c in range(n_cols)]
    maxs = [max(r[c] for r in rows) for c in range(n_cols)]

    result = []
    for r in rows:
        new_row = []
        for c in range(n_cols):
            lo, hi = mins[c], maxs[c]
            span = hi - lo
            if span == 0:
                new_row.append(0.0)
            else:
                new_row.append(float((r[c] - lo) / span))
        result.append(new_row)
    return result

