import math


def _gauss_solve(A, b):
    n = len(A)
    M = [list(map(float, A[i])) + [float(b[i])] for i in range(n)]
    scale = max([abs(M[i][j]) for i in range(n) for j in range(n)] + [0.0])
    if scale == 0.0:
        return None
    tol = scale * 1e-10
    for col in range(n):
        piv = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[piv][col]) <= tol:
            return None
        M[col], M[piv] = M[piv], M[col]
        for r in range(col + 1, n):
            f = M[r][col] / M[col][col]
            if f != 0.0:
                for k in range(col, n + 1):
                    M[r][k] -= f * M[col][k]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n] - sum(M[i][k] * x[k] for k in range(i + 1, n))
        x[i] = s / M[i][i]
    return x


def _jacobi_eig(A):
    n = len(A)
    A = [list(map(float, r)) for r in A]
    V = [[1.0 if i == j else 0.0 for j in range(n)] for i in range(n)]
    for _ in range(200):
        off = sum(A[i][j] ** 2 for i in range(n) for j in range(n) if i != j)
        total = sum(A[i][j] ** 2 for i in range(n) for j in range(n))
        if off <= 1e-30 * max(total, 1e-300):
            break
        for p in range(n):
            for q in range(p + 1, n):
                apq = A[p][q]
                if apq == 0.0:
                    continue
                theta = (A[q][q] - A[p][p]) / (2.0 * apq)
                sgn = 1.0 if theta >= 0 else -1.0
                t = sgn / (abs(theta) + math.sqrt(theta * theta + 1.0))
                c = 1.0 / math.sqrt(t * t + 1.0)
                s = t * c
                for k in range(n):
                    akp, akq = A[k][p], A[k][q]
                    A[k][p] = c * akp - s * akq
                    A[k][q] = s * akp + c * akq
                for k in range(n):
                    apk, aqk = A[p][k], A[q][k]
                    A[p][k] = c * apk - s * aqk
                    A[q][k] = s * apk + c * aqk
                for k in range(n):
                    vkp, vkq = V[k][p], V[k][q]
                    V[k][p] = c * vkp - s * vkq
                    V[k][q] = s * vkp + c * vkq
    return [A[i][i] for i in range(n)], V


def _pinv_solve(A, b):
    n = len(A)
    vals, V = _jacobi_eig(A)
    mx = max([abs(v) for v in vals] + [0.0])
    tol = mx * max(n, 1) * 1e-10
    x = [0.0] * n
    for j in range(n):
        lam = vals[j]
        if abs(lam) <= tol or lam == 0.0:
            continue
        proj = sum(V[i][j] * b[i] for i in range(n)) / lam
        for i in range(n):
            x[i] += proj * V[i][j]
    return x


def masked_linear_regression(rows, columns, target, keep_values=None):
    if not rows:
        raise ValueError("rows must not be empty")
    columns = list(columns)
    if target not in columns:
        raise ValueError("target not in columns")
    ncol = len(columns)
    data = []
    for r in rows:
        r = list(r)
        if len(r) != ncol:
            raise ValueError("row length does not match columns")
        if keep_values is not None:
            r = [v if v in keep_values else 0 for v in r]
        data.append([float(v) for v in r])
    ti = columns.index(target)
    feat_idx = [i for i in range(ncol) if i != ti]
    m = len(data)
    p = len(feat_idx)
    y = [row[ti] for row in data]
    X = [[row[i] for i in feat_idx] for row in data]
    ymean = sum(y) / m
    if p == 0:
        return ([], ymean)
    xmean = [sum(X[r][j] for r in range(m)) / m for j in range(p)]
    Xc = [[X[r][j] - xmean[j] for j in range(p)] for r in range(m)]
    yc = [v - ymean for v in y]
    A = [[sum(Xc[r][i] * Xc[r][j] for r in range(m)) for j in range(p)] for i in range(p)]
    b = [sum(Xc[r][i] * yc[r] for r in range(m)) for i in range(p)]
    coef = _gauss_solve(A, b)
    if coef is None:
        coef = _pinv_solve(A, b)
    intercept = ymean - sum(coef[j] * xmean[j] for j in range(p))
    return ([float(c) for c in coef], float(intercept))

