import numpy as np


def _exact_solve(X, y):
    # X: list of feature rows, y: list of targets. Solve the centered normal equations exactly.
    try:
        Xf = [[Fraction(v) for v in r] for r in X]
        yf = [Fraction(v) for v in y]
    except (ValueError, OverflowError, TypeError):
        return None
    n = len(yf)
    p = len(Xf[0]) if Xf else 0
    ymean = sum(yf) / n
    if p == 0:
        return [], float(ymean)
    xmean = [sum(r[j] for r in Xf) / n for j in range(p)]
    Xc = [[r[j] - xmean[j] for j in range(p)] for r in Xf]
    yc = [v - ymean for v in yf]
    A = [[sum(Xc[k][i] * Xc[k][j] for k in range(n)) for j in range(p)] for i in range(p)]
    b = [sum(Xc[k][i] * yc[k] for k in range(n)) for i in range(p)]
    M = [A[i] + [b[i]] for i in range(p)]
    for col in range(p):
        piv = None
        for r in range(col, p):
            if M[r][col] != 0:
                piv = r
                break
        if piv is None:
            return None
        M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        M[col] = [v / pv for v in M[col]]
        for r in range(p):
            if r != col and M[r][col] != 0:
                f = M[r][col]
                M[r] = [a - f * c for a, c in zip(M[r], M[col])]
    coef = [M[i][p] for i in range(p)]
    intercept = ymean - sum(c * m for c, m in zip(coef, xmean))
    return [float(c) for c in coef], float(intercept)


def _numeric_solve(X, y):
    Xa = np.asarray(X, dtype=float)
    ya = np.asarray(y, dtype=float)
    n = ya.shape[0]
    if Xa.size == 0:
        Xa = Xa.reshape(n, 0)
    ymean = ya.mean()
    if Xa.shape[1] == 0:
        return [], float(ymean)
    xmean = Xa.mean(axis=0)
    coef, *_ = np.linalg.lstsq(Xa - xmean, ya - ymean, rcond=None)
    intercept = ymean - float(np.dot(xmean, coef))
    return [float(c) for c in coef], float(intercept)


def masked_linear_regression(rows, columns, target, keep_values=None):
    if rows is None or len(rows) == 0:
