        r = list(r)
        if len(r) != ncol:
            raise ValueError("row length does not match number of columns")
        table.append(r)
    if keep_values is not None:
        keep = list(keep_values)
        try:
            keep_set = set(keep)
        except TypeError:
            keep_set = None
        def kept(v):
            if keep_set is not None:
                try:
                    return v in keep_set
                except TypeError:
                    pass
            return v in keep
        table = [[v if kept(v) else 0 for v in r] for r in table]
