import math

def standardization_mse(rows):
    if not rows or not rows[0]:
        return 0.0
    n = len(rows)
    m = len(rows[0])
    total = []
    for j in range(m):
        col = [float(r[j]) for r in rows]
        if all(v == col[0] for v in col):
            z = [0.0] * n
        else:
            mean = math.fsum(col) / n
            var = math.fsum((v - mean) ** 2 for v in col) / n
            std = math.sqrt(var)
            if std == 0:
                z = [0.0] * n
            else:
                z = [(v - mean) / std for v in col]
        for v, s in zip(col, z):
            total.append((v - s) ** 2)
    return float(math.fsum(total) / (n * m))

