import re

_NUM_RE = re.compile(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?')
_INT_RE = re.compile(r'[+-]?\d+')


def _is_numeric(value):
    if value is None:
        return False
    return _NUM_RE.fullmatch(value.strip()) is not None


def _to_number(value):
    s = value.strip()
    if _INT_RE.fullmatch(s):
        return int(s)
    return float(s)


def sort_csv_rows(csv_text, sort_key):
    reader = csv.reader(io.StringIO(csv_text))
    header = None
    for row in reader:
        if row:
            header = row
            break
    if header is None or sort_key not in header:
        raise ValueError("Column not found: %r" % (sort_key,))

    rows = []
    for raw in reader:
        if not raw:
            continue
        row = {}
        for i, name in enumerate(header):
            row[name] = raw[i] if i < len(raw) else ''
        rows.append(row)

    if rows:
        for name in dict.fromkeys(header):
            if all(_is_numeric(r[name]) for r in rows):
                for r in rows:
                    r[name] = _to_number(r[name])

    return sorted(rows, key=lambda r: r[sort_key])

