def _solve(A, b):
    n = len(A)
    M = [list(map(float, A[i])) + [float(b[i])] for i in range(n)]
    for k in range(n):
        piv = max(range(k, n), key=lambda i: abs(M[i][k]))
        if M[piv][k] == 0.0:
            raise ValueError("singular system")
        M[k], M[piv] = M[piv], M[k]
        for i in range(k + 1, n):
            f = M[i][k] / M[k][k]
            if f != 0.0:
                for j in range(k, n + 1):
                    M[i][j] -= f * M[k][j]
    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n] - sum(M[i][j] * x[j] for j in range(i + 1, n))
        x[i] = s / M[i][i]
    return x


def _lstsq_min_norm(A, b, n, p):
    # Householder QR with column pivoting; A is list of rows (n x p)
    cols = [[float(A[i][j]) for i in range(n)] for j in range(p)]
    bb = [float(v) for v in b]
    perm = list(range(p))
    eps = 2.220446049250313e-16
    r = 0
    tol = None
    for k in range(min(n, p)):
        norms = [math.sqrt(sum(c[i] * c[i] for i in range(k, n))) for c in cols[k:]]
        jmax = max(range(len(norms)), key=lambda t: norms[t]) + k
        nrm = norms[jmax - k]
        if tol is None:
            tol = max(n, p) * eps * nrm * 10
        if nrm <= tol or nrm == 0.0:
            break
        cols[k], cols[jmax] = cols[jmax], cols[k]
        perm[k], perm[jmax] = perm[jmax], perm[k]
        a = cols[k]
        alpha = -nrm if a[k] >= 0 else nrm
        v = [a[i] for i in range(k, n)]
        v[0] -= alpha
        vn2 = sum(t * t for t in v)
        if vn2 > 0.0:
            for j in range(k, p):
                c = cols[j]
                s = 2.0 * sum(v[i - k] * c[i] for i in range(k, n)) / vn2
                if s != 0.0:
                    for i in range(k, n):
                        c[i] -= s * v[i - k]
            s = 2.0 * sum(v[i - k] * bb[i] for i in range(k, n)) / vn2
            for i in range(k, n):
                bb[i] -= s * v[i - k]
        r = k + 1
    w = [0.0] * p
    if r == 0:
        return w
    R = [[cols[j][i] if j >= i else 0.0 for j in range(p)] for i in range(r)]
    d = bb[:r]
    if r == p:
        z = [0.0] * p
        for i in range(p - 1, -1, -1):
            s = d[i] - sum(R[i][j] * z[j] for j in range(i + 1, p))
            z[i] = s / R[i][i]
    else:
        S = [[sum(R[i][t] * R[j][t] for t in range(p)) for j in range(r)] for i in range(r)]
        u = _solve(S, d)
        z = [sum(R[i][j] * u[i] for i in range(r)) for j in range(p)]
    for j in range(p):
        w[perm[j]] = z[j]
    return w


def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    train_X = list(train_X)
    train_y = list(train_y)
    test_X = list(test_X)
    test_y = list(test_y)
    if len(train_X) == 0 or len(train_y) == 0:
        raise ValueError("training set is empty")
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y have different lengths")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y have different lengths")
    if len(test_X) == 0:
        raise ValueError("test set is empty")
    p = len(train_X[0])
    for row in train_X:
        if len(row) != p:
            raise ValueError("inconsistent number of features in train_X")
    for row in test_X:
        if len(row) != p:
            raise ValueError("inconsistent number of features in test_X")
    n = len(train_X)
    X = [[float(v) for v in row] for row in train_X]
    y = [float(v) for v in train_y]
    xm = [sum(X[i][j] for i in range(n)) / n for j in range(p)]
    ym = sum(y) / n
    if p > 0:
        Xc = [[X[i][j] - xm[j] for j in range(p)] for i in range(n)]
        yc = [v - ym for v in y]
        w = _lstsq_min_norm(Xc, yc, n, p)
    else:
        w = []
    intercept = ym - sum(xm[j] * w[j] for j in range(p))
    preds = [intercept + sum(float(row[j]) * w[j] for j in range(p)) for row in test_X]
    ty = [float(v) for v in test_y]
    tm = sum(ty) / len(ty)
    ss_res = sum((a - b) ** 2 for a, b in zip(ty, preds))
    ss_tot = sum((a - tm) ** 2 for a in ty)
    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0
    return float(1.0 - ss_res / ss_tot)

