            arr = arr.reshape(0, 0)
        else:
            arr = arr.reshape(-1, 1)
    if arr.ndim != 2:
        raise ValueError(f"{name} must be a list of rows")
    return arr


def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    if len(train_X) == 0 or len(train_y) == 0:
        raise ValueError("Training set must not be empty")
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y must have the same length")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y must have the same length")
    if len(test_X) == 0:
        raise ValueError("Test set must not be empty")

    Xtr = _to_2d(train_X, "train_X")
    ytr = np.asarray(train_y, dtype=float).ravel()
    Xte = _to_2d(test_X, "test_X")
    yte = np.asarray(test_y, dtype=float).ravel()

    if Xte.shape[1] != Xtr.shape[1]:
        raise ValueError("train_X and test_X must have the same number of features")

    # Center data so the intercept is handled exactly (as scikit-learn does)
    x_mean = Xtr.mean(axis=0) if Xtr.shape[1] > 0 else np.zeros(0)
    y_mean = ytr.mean()
    Xc = Xtr - x_mean
    yc = ytr - y_mean

    if Xtr.shape[1] > 0:
        coef, _, _, _ = np.linalg.lstsq(Xc, yc, rcond=None)
    else:
        coef = np.zeros(0)
    intercept = y_mean - float(np.dot(x_mean, coef)) if coef.size else y_mean

    pred = Xte @ coef + intercept if coef.size else np.full(yte.shape, intercept)

    if yte.shape[0] < 2:
        return float("nan")

    ss_res = float(np.sum((yte - pred) ** 2))
    ss_tot = float(np.sum((yte - yte.mean()) ** 2))
    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0
    return float(1.0 - ss_res / ss_tot)

