        raise ValueError("articles list is empty")
    try:
        tz = ZoneInfo(timezone)
    except Exception as e:
        raise ValueError("Invalid timezone: %r" % (timezone,)) from e
    hours_by_cat = {}
    for art in articles:
        if not isinstance(art, dict) or 'category' not in art or 'published_time' not in art:
            raise ValueError("Each article must have 'category' and 'published_time'")
        dt = _parse_iso(art['published_time']).astimezone(tz)
        hours_by_cat.setdefault(art['category'], []).append(dt.hour)
    result = {}
    try:
        keys = sorted(hours_by_cat)
    except TypeError:
        keys = list(hours_by_cat)
    for cat in keys:
        hrs = hours_by_cat[cat]
        result[cat] = {
            'count': len(hrs),
            'mean': sum(hrs) / len(hrs),
            'min': min(hrs),
            'max': max(hrs),
        }
    return result

