from fractions import Fraction


def _rref(M, nvars):
    M = [row[:] for row in M]
    rows = len(M)
    r = 0
    for c in range(nvars):
        piv = None
        for i in range(r, rows):
            if M[i][c] != 0:
                piv = i
                break
        if piv is None:
            continue
        M[r], M[piv] = M[piv], M[r]
        pv = M[r][c]
        M[r] = [v / pv for v in M[r]]
        for i in range(rows):
            if i != r and M[i][c] != 0:
                f = M[i][c]
                M[i] = [a - f * b for a, b in zip(M[i], M[r])]
        r += 1
        if r == rows:
            break
    return M[:r]


def _solve_square(A, b):
    n = len(A)
    aug = [A[i][:] + [b[i]] for i in range(n)]
    red = _rref(aug, n)
    return [red[i][n] for i in range(n)]


def filtered_regression_coefficients(rows, height, weight, columns):
    target = columns[0]
    predictors = list(columns[1:])
    hcol, wcol = columns[1], columns[2]
    sel = [r for r in rows if r[hcol] > height and r[wcol] < weight]
    if not sel:
        return None
    X = []
    y = []
    for r in sel:
        X.append([Fraction(1)] + [Fraction(r[p]) for p in predictors])
        y.append(Fraction(r[target]))
    n = len(predictors) + 1
    A = [[Fraction(0)] * n for _ in range(n)]
    b = [Fraction(0)] * n
    for xi, yi in zip(X, y):
        for i in range(n):
            xv = xi[i]
            if xv == 0:
                continue
            b[i] += xv * yi
            Ai = A[i]
            for j in range(n):
                Ai[j] += xv * xi[j]
    aug = [A[i][:] + [b[i]] for i in range(n)]
    R = _rref(aug, n)
    R = [row for row in R if any(v != 0 for v in row[:n])]
    k = len(R)
    if k == n:
        # full rank: R is identity
        coef = [Fraction(0)] * n
        for row in R:
            for j in range(n):
                if row[j] == 1:
                    coef[j] = row[n]
                    break
    elif k == 0:
        coef = [Fraction(0)] * n
    else:
        Rm = [row[:n] for row in R]
        c = [row[n] for row in R]
        G = [[sum(Rm[i][t] * Rm[j][t] for t in range(n)) for j in range(k)] for i in range(k)]
        w = _solve_square(G, c)
        coef = [sum(Rm[i][j] * w[i] for i in range(k)) for j in range(n)]
    result = {'const': float(coef[0])}
    for idx, p in enumerate(predictors):
        result[p] = float(coef[idx + 1])
    return result

