import math


def _parse_number(value):
    """Return a finite float for value, or None if it is not numeric."""
    text = value.strip()
    if not text:
        return None
    try:
        number = float(text)
    except ValueError:
        return None
    if not math.isfinite(number):
        return None
    return number


def _scale(values):
    lo = min(values)
    hi = max(values)
    if lo == hi:
        return [0.0 for _ in values]
    rng = hi - lo
    if math.isfinite(rng):
        scaled = [(v - lo) / rng for v in values]
    else:
        # Avoid overflow for extremely large ranges.
        half_lo = lo / 2.0
        half_rng = hi / 2.0 - half_lo
        scaled = [(v / 2.0 - half_lo) / half_rng for v in values]
    return [min(1.0, max(0.0, s)) for s in scaled]


def normalize_numeric_columns(csv_text):
    if csv_text.startswith('\ufeff'):
        csv_text = csv_text[1:]
    reader = csv.reader(io.StringIO(csv_text, newline=''))
    header = None
    rows = []
    for row in reader:
        if not row or all(cell.strip() == '' for cell in row):
            continue
        if header is None:
            header = row
        else:
            rows.append(row)
    if header is None:
        raise ValueError('CSV data has no header row')

    width = len(header)
    columns = [[] for _ in range(width)]
    for row in rows:
        if len(row) < width:
            row = row + [''] * (width - len(row))
        for i in range(width):
            columns[i].append(row[i])

    result = {}
    found_numeric = False
    for name, values in zip(header, columns):
        parsed = [_parse_number(v) for v in values]
        if values and all(p is not None for p in parsed):
            result[name] = _scale(parsed)
            found_numeric = True
        else:
            result[name] = list(values)

