import math


def student_score_stats(test_scores, student):
    students = list(test_scores['Student'])
    scores = list(test_scores['Score'])
    selected = [float(sc) for st, sc in zip(students, scores) if st == student]
    if not selected:
        raise ValueError("Student not found in data: {!r}".format(student))
    n = len(selected)
    mean = sum(selected) / n
    if n < 2:
        std = float('nan')
    else:
        var = sum((x - mean) ** 2 for x in selected) / (n - 1)
        std = math.sqrt(var)
    return [mean, std]

