import math
import re

_ESC = {'n': '\n', 't': '\t', 'r': '\r', '0': '\0', '\\': '\\', '"': '"', '/': '/', 'a': '\a',
        'b': '\b', 'e': '\x1b', 'f': '\f', 'v': '\v', ' ': ' ', 'N': '\x85', '_': '\xa0',
        'L': '\u2028', 'P': '\u2029', '\t': '\t'}
_HEXLEN = {'x': 2, 'u': 4, 'U': 8}
_INT = re.compile(r'[-+]?[0-9][0-9_]*$')
_HEX = re.compile(r'[-+]?0x[0-9a-fA-F_]+$')
_OCT = re.compile(r'[-+]?0o[0-7_]+$')
_BIN = re.compile(r'[-+]?0b[01_]+$')
_FLOAT = re.compile(r'[-+]?(\.[0-9]+|[0-9][0-9_]*(\.[0-9_]*)?)([eE][-+]?[0-9]+)?$')
_INF = re.compile(r'[-+]?\.(inf|Inf|INF)$')
_NAN = re.compile(r'\.(nan|NaN|NAN)$')


def _quote_end(s, start):
    q = s[start]
    i = start + 1
    while i < len(s):
        c = s[i]
        if q == '"' and c == '\\':
            i += 2
            continue
        if c == q:
            if q == "'" and i + 1 < len(s) and s[i + 1] == "'":
                i += 2
                continue
            return i
        i += 1
    return -1


def _unescape(s):
    out = []
    i = 0
    while i < len(s):
        c = s[i]
        if c == '\\' and i + 1 < len(s):
            e = s[i + 1]
            if e in _HEXLEN:
                ln = _HEXLEN[e]
                try:
                    out.append(chr(int(s[i + 2:i + 2 + ln], 16)))
                    i += 2 + ln
                    continue
                except ValueError:
                    pass
            out.append(_ESC.get(e, e))
            i += 2
            continue
        out.append(c)
        i += 1
    return ''.join(out)


def _resolve(t):
    if t in ('', '~', 'null', 'Null', 'NULL'):
        return None
    if t in ('true', 'True', 'TRUE', 'yes', 'Yes', 'YES', 'on', 'On', 'ON'):
        return True
    if t in ('false', 'False', 'FALSE', 'no', 'No', 'NO', 'off', 'Off', 'OFF'):
        return False
    u = t.replace('_', '')
    try:
        if _INT.match(t):
            return int(u)
        if _HEX.match(t):
            return int(u, 16)
        if _OCT.match(t):
            return int(u, 8)
        if _BIN.match(t):
            return int(u, 2)
        if _FLOAT.match(t):
            return float(u)
    except ValueError:
        pass
    if _INF.match(t):
        return float('-inf') if t[0] == '-' else float('inf')
    if _NAN.match(t):
        return float('nan')
    return t


def _scalar(text):
    t = text.strip()
    if t and t[0] in '"\'':
        e = _quote_end(t, 0)
        if e < 0:
            e = len(t)
        inner = t[1:e]
        if t[0] == "'":
            return inner.replace("''", "'")
        return _unescape(inner)
    return _resolve(t)


def _hashable(k):
    if isinstance(k, list):
        return tuple(_hashable(x) for x in k)
    if isinstance(k, dict):
        return tuple((a, _hashable(b)) for a, b in k.items())
    return k


def _strip_comment(line):
    in_s = in_d = False
    i = 0
    while i < len(line):
        c = line[i]
        if in_d:
            if c == '\\':
                i += 2
                continue
            if c == '"':
                in_d = False
        elif in_s:
            if c == "'":
                if i + 1 < len(line) and line[i + 1] == "'":
                    i += 2
                    continue
                in_s = False
        else:
            if c == '#' and (i == 0 or line[i - 1] in ' \t'):
                return line[:i].rstrip()
            if c in '"\'' and (i == 0 or line[i - 1] in ' \t:[{,-?'):
                if c == '"':
                    in_d = True
                else:
                    in_s = True
        i += 1
    return line.rstrip()


def _is_seq(c):
    return c == '-' or c.startswith('- ') or c.startswith('-\t')


def _split_key(c):
    if not c:
        return None
    depth = 0
    i = 0
    if c[0] in '"\'':
        e = _quote_end(c, 0)
        if e < 0:
            return None
        i = e + 1
    while i < len(c):
        ch = c[i]
        if ch in '[{':
            depth += 1
        elif ch in ']}':
            depth -= 1
        elif ch == ':' and depth <= 0 and (i + 1 == len(c) or c[i + 1] in ' \t'):
            return c[:i].strip(), c[i + 1:].strip()
        i += 1
    return None


def _balanced(text):
    depth = 0
    i = 0
    while i < len(text):
        c = text[i]
        if c in '"\'' and (i == 0 or text[i - 1] in ' \t:[{,'):
            e = _quote_end(text, i)
            if e < 0:
                return False
            i = e + 1
            continue
        if c in '[{':
            depth += 1
        elif c in ']}':
            depth -= 1
        i += 1
    return depth <= 0


class _Flow:
    def __init__(self, s, parser):
        self.s = s
        self.i = 0
        self.p = parser

    def ws(self):
        while self.i < len(self.s) and self.s[self.i] in ' \t\n\r':
            self.i += 1

    def peek(self):
        return self.s[self.i] if self.i < len(self.s) else ''

    def node(self):
        self.ws()
        anchor = None
        while self.peek() in ('!', '&') and self.peek():
            st = self.i
            while self.i < len(self.s) and self.s[self.i] not in ' \t,[]{}':
                self.i += 1
            tok = self.s[st:self.i]
            if tok.startswith('&'):
                anchor = tok[1:]
            self.ws()
        c = self.peek()
        s = self.s
        if c == '[':
            self.i += 1
            items = []
            while True:
                self.ws()
                if self.peek() in (']', ''):
                    self.i += 1
                    break
                item = self.node()
                self.ws()
                if self.peek() == ':':
                    self.i += 1
                    self.ws()
                    val = None if self.peek() in (',', ']', '') else self.node()
                    item = {_hashable(item): val}
                    self.ws()
                items.append(item)
                if self.peek() == ',':
                    self.i += 1
            val = items
        elif c == '{':
            self.i += 1
            d = {}
            while True:
                self.ws()
                if self.peek() in ('}', ''):
                    self.i += 1
                    break
                k = self.node()
                self.ws()
                v = None
                if self.peek() == ':':
                    self.i += 1
                    self.ws()
                    if self.peek() not in (',', '}', ''):
                        v = self.node()
                    self.ws()
                d[_hashable(k)] = v
                if self.peek() == ',':
                    self.i += 1
            val = d
        elif c in ('"', "'"):
            e = _quote_end(s, self.i)
            if e < 0:
                e = len(s) - 1
            val = _scalar(s[self.i:e + 1])
            self.i = e + 1
        else:
            st = self.i
            while self.i < len(s):
                ch = s[self.i]
                if ch in ',[]{}':
                    break
                if ch == ':' and (self.i + 1 >= len(s) or s[self.i + 1] in ' \t,[]{}'):
                    break
                self.i += 1
            t = s[st:self.i].strip()
            if t.startswith('*'):
                val = self.p.anchors.get(t[1:])
            else:
                val = _resolve(t)
        if anchor:
            self.p.anchors[anchor] = val
        return val


class _Parser:
    def __init__(self, text):
        self.raw = text.splitlines()
        self.lines = []
        self.anchors = {}
        for no, r in enumerate(self.raw):
            st = r.strip()
            if st.startswith('%') and not r.startswith(' '):
                continue
            if st in ('---', '...'):
                continue
            if r.startswith('--- '):
                r = r[4:].strip()
            s = _strip_comment(r)
            if not s.strip():
                continue
            ind = len(s) - len(s.lstrip(' '))
            self.lines.append([ind, s.strip(), no])
        self.n = len(self.lines)

    def parse(self):
        if not self.lines:
            return None
        v, _ = self.parse_block(0, self.lines[0][0])
        return v

    def parse_block(self, idx, indent):
        c = self.lines[idx][1]
        if _is_seq(c):
            return self.parse_seq(idx, indent)
        if _split_key(c) is not None:
            return self.parse_map(idx, indent)
        return self.parse_value(c, idx + 1, indent - 1, self.lines[idx][2], False)

    def parse_key(self, k):
        if k.startswith('*'):
            return _hashable(self.anchors.get(k[1:]))
        if k[:1] in ('[', '{'):
            return _hashable(_Flow(k, self).node())
        if k.startswith('? '):
            k = k[2:]
        return _hashable(_scalar(k))

    def parse_map(self, idx, indent):
        result = {}
        while idx < self.n:
            ind, c, rawno = self.lines[idx]
            if ind < indent:
                break
            if ind > indent:
                raise ValueError('bad indentation at line %d' % (rawno + 1))
            if _is_seq(c):
                break
            kv = _split_key(c)
            if kv is None:
                raise ValueError('expected mapping entry at line %d' % (rawno + 1))
            k, v = kv
            key = self.parse_key(k)
            val, idx = self.parse_value(v, idx + 1, indent, rawno, True)
            if k == '<<' and isinstance(val, (dict, list)):
                srcs = val if isinstance(val, list) else [val]
                for sdict in srcs:
                    if isinstance(sdict, dict):
                        for a, b in sdict.items():
                            result.setdefault(a, b)
                continue
            result[key] = val
        return result, idx

    def parse_seq(self, idx, indent):
        result = []
        while idx < self.n:
            ind, c, rawno = self.lines[idx]
            if ind < indent:
                break
            if ind > indent:
                raise ValueError('bad indentation at line %d' % (rawno + 1))
            if not _is_seq(c):
                break
            rest = c[1:]
            stripped = rest.lstrip(' \t')
            if stripped == '':
                val, idx = self.parse_value('', idx + 1, indent, rawno, False)
            else:
                off = 1 + len(rest) - len(stripped)
                if (_is_seq(stripped) or _split_key(stripped) is not None) and stripped[0] not in '&!*':
                    self.lines[idx] = [ind + off, stripped, rawno]
                    val, idx = self.parse_block(idx, ind + off)
                else:
                    val, idx = self.parse_value(stripped, idx + 1, indent, rawno, False)
            result.append(val)
        return result, idx

    def parse_value(self, v, idx, pind, rawno, in_map):
        anchor = None
        while v and v[0] in '!&':
            parts = v.split(None, 1)
            tok = parts[0]
            v = parts[1] if len(parts) > 1 else ''
            if tok[0] == '&':
                anchor = tok[1:]
        lines = self.lines
        if v.startswith('*'):
            val = self.anchors.get(v[1:].strip())
        elif v == '':
            val = None
            if idx < self.n:
                ind, c, _ = lines[idx]
                if ind > pind or (in_map and ind == pind and _is_seq(c)):
                    val, idx = self.parse_block(idx, ind)
        elif v[0] in '|>':
            val, idx = self.block_scalar(v, idx, pind, rawno)
        elif v[0] in '[{':
            text = v
            while not _balanced(text) and idx < self.n:
                text += ' ' + lines[idx][1]
                idx += 1
            val = _Flow(text, self).node()
        else:
            text = v
            if v[0] in '"\'':
                while _quote_end(text, 0) < 0 and idx < self.n:
                    text += ' ' + lines[idx][1]
                    idx += 1
            else:
                while (idx < self.n and lines[idx][0] > pind and _split_key(lines[idx][1]) is None
                       and not _is_seq(lines[idx][1])):
                    text += ' ' + lines[idx][1]
                    idx += 1
            val = _scalar(text)
        if anchor:
            self.anchors[anchor] = val
        return val, idx

    def block_scalar(self, header, idx, pind, rawno):
        style = header[0]
        chomp = ''
        explicit = None
        for ch in header[1:]:
            if ch in '+-':
                chomp = ch
            elif ch.isdigit():
                explicit = int(ch)
        bind = None
        if explicit:
            bind = max(pind, 0) + explicit
        raws = self.raw
        i = rawno + 1
        body = []
        while i < len(raws):
            r = raws[i]
            if r.strip() == '':
                body.append('')
                i += 1
                continue
            ri = len(r) - len(r.lstrip(' '))
            if bind is None:
                if ri <= pind:
                    break
                bind = ri
            if ri < bind:
                break
            body.append(r[bind:])
            i += 1
        last = i - 1
        while idx < self.n and self.lines[idx][2] <= last:
            idx += 1
        k = len(body)
        while k > 0 and body[k - 1] == '':
            k -= 1
        content = body[:k]
        trailing = body[k:]
        if style == '|':
            s = '\n'.join(content)
        else:
            def more(x):
                return x[:1] in (' ', '\t')
            parts = []
            for j, l in enumerate(content):
                if j == 0:
                    parts.append(l)
                    continue
                p = content[j - 1]
                if l == '':
                    parts.append('\n')
                elif p == '':
                    q = ''
                    for jj in range(j - 1, -1, -1):
                        if content[jj] != '':
                            q = content[jj]
                            break
                    parts.append('\n' + l if (more(q) or more(l)) else l)
                elif more(p) or more(l):
                    parts.append('\n' + l)
                else:
                    parts.append(' ' + l)
            s = ''.join(parts)
        if chomp == '-':
            return s, idx
        if not content:
            return ('\n' * len(trailing) if chomp == '+' else ''), idx
        if chomp == '+':
            return s + '\n' + '\n' * len(trailing), idx
        return s + '\n', idx


def cosine_yaml_key(yaml_text, key):
    data = _Parser(yaml_text).parse()
    if data is None:
        data = {}
    if isinstance(data, dict) and key in data:
        data[key] = math.cos(float(data[key]))
    return data

