    denom = m * sxx - sx * sx
    if denom == 0:
        return 0.0, float(sy / m)
    slope = (m * sxy - sx * sy) / denom
    intercept = (sy * sxx - sx * sxy) / denom
    return float(slope), float(intercept)


def _fit_float(xs, ys):
    m = len(xs)
    mx = sum(xs) / m
    my = sum(ys) / m
    sxx = sum((x - mx) ** 2 for x in xs)
    sxy = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    if sxx == 0:
        return 0.0, my
    slope = sxy / sxx
    return slope, my - slope * mx


def top_regression_residuals(data, feature, target, n=10):
