    if len(xs) != len(ys):
        raise ValueError("Columns must have equal length")
    if len(xs) == 0:
        raise ValueError("Cannot fit a regression on empty data")
    try:
        slope, intercept = _fit_exact(xs, ys)
    except (ValueError, OverflowError, TypeError, ZeroDivisionError):
        xs = [float(v) for v in xs]
        ys = [float(v) for v in ys]
        slope, intercept = _fit_float(xs, ys)
    residuals = [y - (slope * x + intercept) for x, y in zip(xs, ys)]
    order = sorted(range(len(residuals)), key=lambda i: -abs(residuals[i]))
    if n is None:
        k = len(order)
    else:
        k = max(0, int(n))
    return order[:k], slope, intercept

