            for j in range(k):
                d = _sqdist(p, centroids[j])
                if best_d is None or d < best_d:
                    best_d, best_j = d, j
            new.append(best_j)
        counts = [0] * k
        for a in new:
            counts[a] += 1
        for j in range(k):
            if counts[j] == 0:
