def _lloyd(X, centers, max_iter=300):
    k = len(centers)
    centers = centers.copy()
    labels = None
    for _ in range(max_iter):
        d = ((X[:, None, :] - centers[None, :, :]) ** 2).sum(axis=2)
        new_labels = d.argmin(axis=1)
        # handle empty clusters
        counts = np.bincount(new_labels, minlength=k)
        if (counts == 0).any():
            mind = d[np.arange(len(X)), new_labels].copy()
            for c in np.where(counts == 0)[0]:
                # take the point farthest from its centroid among clusters with >1 member
                order = np.argsort(-mind)
                for idx in order:
                    if counts[new_labels[idx]] > 1:
                        counts[new_labels[idx]] -= 1
                        new_labels[idx] = c
                        counts[c] += 1
                        mind[idx] = 0.0
                        break
        for c in range(k):
            members = X[new_labels == c]
            if len(members):
                centers[c] = members.mean(axis=0)
        if labels is not None and np.array_equal(labels, new_labels):
            labels = new_labels
            break
