    for _ in range(1, k):
        nxt = int(mind.argmax())
        idxs.append(nxt)
        mind = np.minimum(mind, ((X - X[nxt]) ** 2).sum(axis=1))
    return X[idxs].copy()


def _kmeanspp(X, k, rng):
