import re

_INT_RE = re.compile(r'^[+-]?\d+$')
_FLOAT_RE = re.compile(r'^[+-]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?$')


def _convert(value):
    if value is None:
        return None
    s = value.strip()
    if s == '':
        return None
    if _INT_RE.match(s):
        try:
            return int(s)
        except ValueError:
            pass
    if _FLOAT_RE.match(s):
        try:
            return float(s)
        except ValueError:
            pass
    return value


def merge_csv_texts(csv_texts):
    if not csv_texts:
        return []
    columns = []
    seen = set()
    parsed = []  # list of (header, rows)
    for text in csv_texts:
        if text is None:
            continue
        if isinstance(text, bytes):
            text = text.decode('utf-8')
        if text.startswith('\ufeff'):
            text = text[1:]
        reader = csv.reader(io.StringIO(text))
        header = None
        rows = []
        for row in reader:
            if not row or all(c.strip() == '' for c in row):
                if header is None:
                    continue
                if not row:
                    continue
                # row of only empty cells: skip as blank line
                continue
            if header is None:
                header = [h.strip() for h in row]
                continue
            rows.append(row)
        if header is None:
            continue
        for h in header:
            if h not in seen:
                seen.add(h)
                columns.append(h)
        parsed.append((header, rows))

    result = []
