import math


def _sqdist(a, b):
    dx = a[0] - b[0]
    dy = a[1] - b[1]
    return dx * dx + dy * dy


def _farthest_first(points, k, start):
    centers = [points[start]]
    mind = [_sqdist(p, centers[0]) for p in points]
    while len(centers) < k:
        best_i = 0
        best_d = -1.0
        for i, d in enumerate(mind):
            if d > best_d:
                best_d = d
                best_i = i
        c = points[best_i]
        centers.append(c)
        for i, p in enumerate(points):
            d = _sqdist(p, c)
            if d < mind[i]:
                mind[i] = d
    return centers


def _assign(points, centers):
    labels = []
    total = 0.0
    for p in points:
        best_j = 0
        best_d = None
        for j, c in enumerate(centers):
            d = _sqdist(p, c)
            if best_d is None or d < best_d:
                best_d = d
                best_j = j
        labels.append(best_j)
        total += best_d
    return labels, total


def _lloyd(points, centers, max_iter=300):
    k = len(centers)
    centers = list(centers)
    labels, inertia = _assign(points, centers)
    for _ in range(max_iter):
        sx = [0.0] * k
        sy = [0.0] * k
        cnt = [0] * k
        for p, l in zip(points, labels):
            sx[l] += p[0]
            sy[l] += p[1]
            cnt[l] += 1
        new_centers = []
        for j in range(k):
            if cnt[j]:
                new_centers.append((sx[j] / cnt[j], sy[j] / cnt[j]))
            else:
                new_centers.append(centers[j])
        centers = new_centers
        new_labels, inertia = _assign(points, centers)
        if new_labels == labels:
            break
        labels = new_labels
    return labels, inertia


def cluster_point_labels(data, n_clusters):
    if not data:
        raise ValueError("data must not be empty")
    try:
        k = int(n_clusters)
    except (TypeError, ValueError):
        raise ValueError("n_clusters must be an integer")
    if k != n_clusters or k < 1:
        raise ValueError("n_clusters must be a positive integer")
    points = []
    for item in data:
        try:
            _, x, y = item
            points.append((float(x), float(y)))
        except (TypeError, ValueError):
            raise ValueError("each item must be an (identifier, x, y) tuple with numeric coordinates")
    n = len(points)
    if k > n:
        raise ValueError("n_clusters cannot exceed the number of points")

    best_labels = None
    best_inertia = None
    for start in range(min(n, 10)):
        centers = _farthest_first(points, k, start)
        labels, inertia = _lloyd(points, centers)
        if best_inertia is None or inertia < best_inertia - 1e-12 * max(1.0, abs(best_inertia)):
            best_inertia = inertia
            best_labels = labels

    mapping = {}
    result = []
    for l in best_labels:
        if l not in mapping:
            mapping[l] = len(mapping)
        result.append(mapping[l])
    return result

