from fractions import Fraction


def summarize_histogram(values, bins):
    if not values:
        raise ValueError("values must be non-empty")
    bins = int(bins)
    if bins <= 0:
        raise ValueError("bins must be positive")
    mean = statistics.mean(values)
    std = statistics.pstdev(values)
    counts = [0] * bins
    lo = min(values)
    hi = max(values)
    flo = Fraction(lo)
    span = Fraction(hi) - flo
    for v in values:
        if span == 0:
            idx = 0
        else:
            idx = math.floor((Fraction(v) - flo) * bins / span)
            if idx >= bins:
                idx = bins - 1
            elif idx < 0:
                idx = 0
        counts[idx] += 1
    return (mean, std, counts)

