def _ends_cvc(w):
    return (len(w) >= 3 and _cons(w, len(w) - 3) and not _cons(w, len(w) - 2)
            and _cons(w, len(w) - 1) and w[-1] not in ('w', 'x', 'y')) or \
           (len(w) == 2 and not _cons(w, 0) and _cons(w, 1))


def _rep(w, suf, r):
    if suf == '':
        return w + r
    return w[:-len(suf)] + r


def _apply(w, rules):
    for suf, r, cond in rules:
        if suf == '*d' and _ends_double(w):
            st = w[:-2]
            if cond is None or cond(st):
                return st + r
            return w
        if w.endswith(suf):
            st = _rep(w, suf, '')
            if cond is None or cond(st):
                return st + r
            return w
    return w


