    if w.endswith('ies') and len(w) == 4:
        return _rep(w, 'ies', 'ie')
    return _apply(w, [('sses', 'ss', None), ('ies', 'i', None), ('ss', 'ss', None), ('s', '', None)])


def _step1b(w):
    if w.endswith('ied'):
        if len(w) == 4:
            return _rep(w, 'ied', 'ie')
        return _rep(w, 'ied', 'i')
    if w.endswith('eed'):
        st = _rep(w, 'eed', '')
        if _measure(st) > 0:
            return st + 'ee'
        return w
    ok = False
    inter = w
    for suf in ('ed', 'ing'):
        if w.endswith(suf):
            inter = _rep(w, suf, '')
            if _has_vowel(inter):
                ok = True
                break
    if not ok:
        return w
    last = inter[-1] if inter else ''
    return _apply(inter, [
        ('at', 'ate', None), ('bl', 'ble', None), ('iz', 'ize', None),
        ('*d', last, lambda s: last not in ('l', 's', 'z')),
        ('', 'e', lambda s: _measure(s) == 1 and _ends_cvc(s)),
    ])


def _step1c(w):
    return _apply(w, [('y', 'i', lambda s: len(s) > 1 and _cons(s, len(s) - 1))])


def _step2(w):
