        return _step2(_rep(w, 'alli', 'al'))
    rules = [
        ('ational', 'ate', _pos), ('tional', 'tion', _pos), ('enci', 'ence', _pos),
        ('anci', 'ance', _pos), ('izer', 'ize', _pos), ('bli', 'ble', _pos),
        ('alli', 'al', _pos), ('entli', 'ent', _pos), ('eli', 'e', _pos),
        ('ousli', 'ous', _pos), ('ization', 'ize', _pos), ('ation', 'ate', _pos),
