        ('icate', 'ic', _pos), ('ative', '', _pos), ('alize', 'al', _pos),
        ('iciti', 'ic', _pos), ('ical', 'ic', _pos), ('ful', '', _pos), ('ness', '', _pos),
    ])


def _step4(w):
