def modes_and_spectrum(data, repetitions):
    data = list(data) if data is not None else []
    if not data or repetitions is None or repetitions <= 0:
        return {'mode': [], 'count': [], 'fft': []}
    repetitions = int(repetitions)
    counts = Counter(data)
    max_count = max(counts.values())
    modes = [v for v, c in counts.items() if c == max_count]
    try:
        modes = sorted(modes)
    except TypeError:
        modes = sorted(modes, key=lambda z: (complex(z).real, complex(z).imag))
