from fractions import Fraction


def _to_frac(v):
    try:
        return Fraction(v)
    except (TypeError, ValueError):
        return Fraction(float(v))


def _numpy_fit(records, keys, target):
    import numpy as np
    X = np.array([[1.0] + [float(r[k]) for k in keys] for r in records], dtype=float)
    y = np.array([float(r[target]) for r in records], dtype=float)
    beta, *_ = np.linalg.lstsq(X, y, rcond=None)
    return float(beta[0]), {k: float(b) for k, b in zip(keys, beta[1:])}


def fit_linear_regression(records, target='z'):
    records = list(records)
    if not records:
        raise ValueError("records must be non-empty")
    keys = [k for k in records[0] if k != target]
    p = len(keys) + 1
    try:
        A = [[Fraction(0)] * p for _ in range(p)]
        b = [Fraction(0)] * p
        for r in records:
            row = [Fraction(1)] + [_to_frac(r[k]) for k in keys]
            yv = _to_frac(r[target])
            for i in range(p):
                ri = row[i]
                if ri == 0:
                    continue
                Ai = A[i]
                for j in range(i, p):
                    Ai[j] += ri * row[j]
                b[i] += ri * yv
        for i in range(p):
            for j in range(i):
                A[i][j] = A[j][i]
        # Gaussian elimination with exact arithmetic
        M = [A[i][:] + [b[i]] for i in range(p)]
        for col in range(p):
            piv = None
            for r_ in range(col, p):
                if M[r_][col] != 0:
                    piv = r_
                    break
            if piv is None:
                raise ZeroDivisionError("singular")
            M[col], M[piv] = M[piv], M[col]
            pv = M[col][col]
            for r_ in range(p):
                if r_ != col and M[r_][col] != 0:
                    f = M[r_][col] / pv
                    Mr = M[r_]
                    Mc = M[col]
                    for c in range(col, p + 1):
                        Mr[c] -= f * Mc[c]
        beta = [M[i][p] / M[i][i] for i in range(p)]
        return float(beta[0]), {k: float(v) for k, v in zip(keys, beta[1:])}
    except (ZeroDivisionError, OverflowError, ValueError, TypeError):
        return _numpy_fit(records, keys, target)

