import math


def _is_missing(v):
    if v is None:
        return True
    try:
        return isinstance(v, float) and math.isnan(v)
    except TypeError:
        return False


def min_max_scale_columns(data, columns):
    cols_to_scale = set(columns)
    for c in cols_to_scale:
        if c not in data:
            raise KeyError(c)
    result = {}
    for name, values in data.items():
        values = list(values)
        if name not in cols_to_scale:
            result[name] = values
            continue
        present = [v for v in values if not _is_missing(v)]
        if not present:
            result[name] = values
            continue
        lo = min(present)
        hi = max(present)
        rng = hi - lo
        scaled = []
        for v in values:
            if _is_missing(v):
                scaled.append(v)
            elif rng == 0:
                scaled.append(0.0)
            else:
                scaled.append((v - lo) / rng)
        result[name] = scaled
    return result

