        value = ''
    value = str(value)
    return value.replace('\r\n', '<br>').replace('\r', '<br>').replace('\n', '<br>')


def encode_csv_column(csv_text, column_name):
    if csv_text is None:
        raise ValueError('No CSV data provided')
    if csv_text.startswith('\ufeff'):
        csv_text = csv_text[1:]
    reader = csv.reader(io.StringIO(csv_text, newline=''))
    header = None
    for row in reader:
        if row:
            header = row
            break
    if header is None:
        raise ValueError('CSV has no header row')
    if column_name not in header:
        raise ValueError('Column %r not found' % (column_name,))
    idx = header.index(column_name)
    values = []
    for row in reader:
        if not row:
            continue
        val = row[idx] if idx < len(row) else ''
        values.append(_clean(val))
    classes = sorted(set(values))
    index = {v: i for i, v in enumerate(classes)}
    codes = [index[v] for v in values]
    return classes, codes

