def _parse_start(start_date):
    if not isinstance(start_date, str) or not re.fullmatch(r'\d{4}-\d{2}-\d{2}', start_date.strip()):
        raise ValueError('Invalid start date: %r' % (start_date,))
    try:
        return datetime.strptime(start_date.strip(), '%Y-%m-%d').date()
    except ValueError:
        raise ValueError('Invalid start date: %r' % (start_date,))


def _make_rule(freq):
    if not isinstance(freq, str):
        raise ValueError('Invalid frequency: %r' % (freq,))
    f = freq.strip().lower()
    if f in ('month-end', 'monthend', 'month_end', 'm'):
        def rule(y, m):
            return date(y, m, calendar.monthrange(y, m)[1])
        return rule
    if f in ('quarter-end', 'quarterend', 'quarter_end', 'q'):
        def rule(y, m):
            if m % 3 != 0:
                return None
            return date(y, m, calendar.monthrange(y, m)[1])
        return rule
    mt = re.fullmatch(r'([1-4])-([A-Za-z]{3})', freq.strip())
    if mt and mt.group(2).upper() in _WEEKDAYS:
        week = int(mt.group(1))
        wd = _WEEKDAYS[mt.group(2).upper()]
        def rule(y, m):
            first_wd = date(y, m, 1).weekday()
            day = 1 + (wd - first_wd) % 7 + 7 * (week - 1)
            return date(y, m, day)
        return rule
    raise ValueError('Invalid frequency: %r' % (freq,))


def forecast_schedule(start_date, freq, sales):
    start = _parse_start(start_date)
    rule = _make_rule(freq)
    sales = list(sales)
