import math

def seasonal_decomposition(values, period, model):
    if model not in ('additive', 'multiplicative'):
        raise ValueError("model must be 'additive' or 'multiplicative'")
    if not isinstance(period, int) or isinstance(period, bool) or period < 1:
        raise ValueError('period must be a positive integer')
    vals = [float(v) for v in values]
    n = len(vals)
    if n < 2 * period:
        raise ValueError('series must contain at least two complete periods')
    mult = model == 'multiplicative'

    h = period // 2
    trend = [None] * n
    for i in range(h, n - h):
        if period % 2 == 1:
            s = math.fsum(vals[i - h:i + h + 1])
        else:
            s = math.fsum([0.5 * vals[i - h]] + vals[i - h + 1:i + h] + [0.5 * vals[i + h]])
        trend[i] = s / period

    buckets = [[] for _ in range(period)]
    for i in range(n):
        t = trend[i]
        if t is None:
            continue
        if mult:
            if t == 0:
                raise ValueError('trend is zero; multiplicative model undefined')
            buckets[i % period].append(vals[i] / t)
        else:
            buckets[i % period].append(vals[i] - t)

    idx = []
    for b in buckets:
        if not b:
            raise ValueError('insufficient data to estimate seasonal indices')
        idx.append(math.fsum(b) / len(b))
    mean_idx = math.fsum(idx) / period
    if mult:
        if mean_idx == 0:
            raise ValueError('cannot normalise seasonal indices')
        idx = [x / mean_idx for x in idx]
    else:
        idx = [x - mean_idx for x in idx]

    seasonal = [idx[i % period] for i in range(n)]
    residual = [None] * n
    for i in range(n):
        t = trend[i]
        if t is None:
            continue
        if mult:
            d = t * seasonal[i]
            if d == 0:
                raise ValueError('cannot compute multiplicative residual')
            residual[i] = vals[i] / d
        else:
            residual[i] = vals[i] - t - seasonal[i]

    return {'trend': trend, 'seasonal': seasonal, 'residual': residual}

