from html.parser import HTMLParser

_VOID = {'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
         'meta', 'param', 'source', 'track', 'wbr', 'keygen', 'command'}


class _ArticleParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.containers = []
        self.stack = []  # (tag, container_idx or None, started_captures)
        self.active = {}  # (idx, field) -> list of text pieces

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in _VOID:
            return
        classes = set()
        for k, v in attrs:
            if k.lower() == 'class' and v:
                classes.update(v.split())
        fields = []
        if tag == 'h1':
            fields.append('title')
        elif tag == 'span':
            if 'date' in classes:
                fields.append('date')
            if 'author' in classes:
                fields.append('author')
        started = []
        if fields:
            for (_, cidx, _) in self.stack:
                if cidx is None:
                    continue
                c = self.containers[cidx]
                for f in fields:
                    if c[f] is None and (cidx, f) not in self.active:
                        self.active[(cidx, f)] = []
                        started.append((cidx, f))
        cidx = None
        if tag == 'div' and 'container' in classes:
            self.containers.append({'title': None, 'date': None, 'author': None})
            cidx = len(self.containers) - 1
        self.stack.append((tag, cidx, started))

    def handle_data(self, data):
        for buf in self.active.values():
            buf.append(data)

    def _pop(self):
        tag, cidx, started = self.stack.pop()
        for key in started:
            buf = self.active.pop(key, None)
            if buf is not None:
                idx, f = key
                if self.containers[idx][f] is None:
                    self.containers[idx][f] = ''.join(buf).strip()

    def handle_endtag(self, tag):
        tag = tag.lower()
        if not any(t == tag for (t, _, _) in self.stack):
            return
        while self.stack:
            t = self.stack[-1][0]
            self._pop()
            if t == tag:
                break

    def close(self):
        super().close()
        while self.stack:
            self._pop()


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()
    result = []
    for c in parser.containers:
        title = c['title'] if c['title'] is not None else 'No Title'
        date = c['date'] if c['date'] is not None else 'No Date'
        author = c['author'] if c['author'] is not None else 'No Author'
        result.append((title, date, author))
    return result

