def standardize_and_correlate(table):
    if not isinstance(table, dict) or not table:
        raise ValueError("table is empty")
    lengths = {len(list(col)) for col in table.values()}
    if len(lengths) != 1:
        raise ValueError("columns must have equal length")
    n = lengths.pop()
    if n == 0:
        raise ValueError("table is empty")

    numeric_names = []
    for name, col in table.items():
        if all(_is_number(v) for v in col):
            numeric_names.append(name)
    if not numeric_names:
        raise ValueError("table has no numeric columns")

    devs = {}
    sums_sq = {}
    standardized = {}
    for name, col in table.items():
        col = list(col)
        if name in numeric_names:
            vals = [float(v) for v in col]
            mean = math.fsum(vals) / n
            d = [v - mean for v in vals]
            ss = math.fsum(x * x for x in d)
            devs[name] = d
            sums_sq[name] = ss
            std = math.sqrt(ss / n)
            if std == 0 or not math.isfinite(std):
                standardized[name] = [0.0] * n if std == 0 else [float('nan')] * n
            else:
                standardized[name] = [x / std for x in d]
        else:
            standardized[name] = col

    k = len(numeric_names)
    corr = [[0.0] * k for _ in range(k)]
    for i in range(k):
        a = numeric_names[i]
        for j in range(i, k):
            b = numeric_names[j]
            sa, sb = sums_sq[a], sums_sq[b]
            if sa == 0 or sb == 0 or not math.isfinite(sa) or not math.isfinite(sb):
                r = float('nan')
            elif i == j:
                r = 1.0
            else:
                sab = math.fsum(x * y for x, y in zip(devs[a], devs[b]))
                denom = math.sqrt(sa) * math.sqrt(sb)
                r = sab / denom
                if r > 1.0:
                    r = 1.0
                elif r < -1.0:
                    r = -1.0
            corr[i][j] = r
            corr[j][i] = r

