import csv
import io
import math


def normalize_csv_column(csv_text, column):
    """Return the z-scores of a numeric CSV column, in row order.

    Each value has the column mean subtracted and is divided by the sample
    standard deviation (n - 1 denominator).

    Raises:
        KeyError: if the column is not in the header.
        ValueError: if a value is missing or not numeric, if there are fewer
            than two values, or if the standard deviation is zero.
    """
    reader = csv.reader(io.StringIO(csv_text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text is empty; expected a header row")

    names = [h.strip() for h in header]
    if column in header:
        idx = header.index(column)
    elif column.strip() in names:
        idx = names.index(column.strip())
    else:
        raise KeyError("Column %r not found in header %r" % (column, header))

    values = []
    for line_no, row in enumerate(reader, start=2):
        if not row or all(not cell.strip() for cell in row):
            continue  # skip blank lines
        if idx >= len(row):
            raise ValueError("Row %d is missing column %r" % (line_no, column))
        cell = row[idx].strip()
        try:
            num = float(cell)
        except ValueError:
            raise ValueError("Row %d: value %r in column %r is not numeric"
                             % (line_no, row[idx], column))
        if not math.isfinite(num):
            raise ValueError("Row %d: value %r in column %r is not finite"
                             % (line_no, row[idx], column))
        values.append(num)

    n = len(values)
    if n < 2:
        raise ValueError("Need at least two values to compute a sample standard deviation")

    mean = math.fsum(values) / n
    var = math.fsum((v - mean) ** 2 for v in values) / (n - 1)
    std = math.sqrt(var)
    if std == 0:
        raise ValueError("Standard deviation of column %r is zero; z-scores are undefined" % column)

    return [(v - mean) / std for v in values]

