def xml_items_to_columns(xml_text):
    try:
        root = ET.fromstring(xml_text)
    except (ET.ParseError, TypeError) as exc:
        raise ValueError("Invalid XML: %s" % exc) from exc

    rows = []
    columns = []
    seen = set()
    for elem in root.iter():
        if elem is root or elem.tag != 'item':
            continue
        row = {}
        for child in elem:
            tag = child.tag
            if not isinstance(tag, str):
                continue
            if tag in row:
                continue
            text = child.text
            row[tag] = text if text else None
            if tag not in seen:
                seen.add(tag)
                columns.append(tag)
        rows.append(row)

    if not rows:
        raise ValueError("No 'item' elements found in XML")

    return {col: [row.get(col) for row in rows] for col in columns}

