    n = len(data[cols[0]])
    keep = [i for i in range(n) if all(data[c][i] is not None for c in cols)]
    result = {}
    for c in cols:
        vals = [data[c][i] for i in keep]
        if not vals:
            result[c] = []
            continue
        mn = min(vals)
        mx = max(vals)
        if mx == mn:
            result[c] = [0.0 for _ in vals]
        else:
            rng = mx - mn
            result[c] = [float((v - mn) / rng) for v in vals]
    return result

