    if not records:
        raise ValueError("column %r does not exist (no records)" % (column_name,))
    if not any(isinstance(r, dict) and column_name in r for r in records):
        raise ValueError("column %r does not exist" % (column_name,))
    raw = [r[column_name] for r in records if isinstance(r, dict) and column_name in r]
    raw = [v for v in raw if v is not None]
    n_bins = 10
    if not raw:
        return [0] * n_bins
    if any(isinstance(v, str) for v in raw):
        distinct = sorted(set(str(v) for v in raw))
        index = {s: i for i, s in enumerate(distinct)}
        values = [float(index[str(v)]) for v in raw]
    else:
        values = [float(v) for v in raw]
    values = [v for v in values if v == v]
    if not values:
        return [0] * n_bins
    lo = min(values)
    hi = max(values)
    if lo == hi:
        lo -= 0.5
        hi += 0.5
    delta = hi - lo
    step = delta / n_bins
    edges = [lo + i * step for i in range(n_bins + 1)]
    edges[-1] = hi
    norm = n_bins / delta
    counts = [0] * n_bins
    for v in values:
        idx = int((v - lo) * norm)
        if idx >= n_bins:
            idx = n_bins - 1
        if idx < 0:
            idx = 0
        if idx > 0 and v < edges[idx]:
            idx -= 1
        elif idx != n_bins - 1 and v >= edges[idx + 1]:
            idx += 1
        counts[idx] += 1
    return counts

