import numpy as np


def column_histogram(records, column_name):
    """Return the counts of a 10-bin equal-width histogram of a column.

    Bins span the column's minimum to maximum, with the maximum counted in
    the last bin. String columns are first replaced by each value's index in
    the sorted list of distinct values. If every value is the same, the
    range is widened by 0.5 on each side, so all values land in bin 5.
    """
    if not records:
        raise ValueError(f"Column {column_name!r} does not exist: no records")
    for row in records:
        if not isinstance(row, dict) or column_name not in row:
            raise ValueError(f"Column {column_name!r} does not exist in the table")

    values = [row[column_name] for row in records]

    if all(isinstance(v, str) for v in values):
        distinct = sorted(set(values))
        index = {v: i for i, v in enumerate(distinct)}
        values = [index[v] for v in values]

    try:
        arr = np.asarray(values, dtype=float)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"Column {column_name!r} contains non-numeric values") from exc

    counts, _ = np.histogram(arr, bins=10)
    return [int(c) for c in counts]

