class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self.stack = []
        self.skip = 0

    def _pop_until(self, stop_kinds):
        while self.stack and self.stack[-1][0] not in stop_kinds:
            self.stack.pop()

    def _find_within_table(self, kind):
        for i in range(len(self.stack) - 1, -1, -1):
            k = self.stack[i][0]
            if k == kind:
                return i
            if k == 'table':
                return -1
        return -1

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in ('script', 'style'):
            self.skip += 1
            return
        if tag == 'table':
            self.stack.append(('table', None))
        elif tag == 'tr':
            self._pop_until(('table',))
            row = []
            self.rows.append(row)
            self.stack.append(('tr', row))
        elif tag in ('td', 'th'):
            self._pop_until(('tr', 'table'))
            if not self.stack or self.stack[-1][0] != 'tr':
                row = []
                self.rows.append(row)
                self.stack.append(('tr', row))
            row = self.stack[-1][1]
            if tag == 'td':
                pieces = []
                row.append(pieces)
                self.stack.append(('td', pieces))
            else:
                self.stack.append(('th', None))

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in ('script', 'style'):
            if self.skip:
                self.skip -= 1
            return
        if tag in ('td', 'th', 'tr'):
            idx = self._find_within_table(tag)
            if idx >= 0:
                del self.stack[idx:]
        elif tag == 'table':
            for i in range(len(self.stack) - 1, -1, -1):
                if self.stack[i][0] == 'table':
                    del self.stack[i:]
                    break

    def handle_data(self, data):
        if self.skip:
            return
        for kind, obj in self.stack:
            if kind == 'td':
                obj.append(data)


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html or '')
    parser.close()
    return [[''.join(cell).strip() for cell in row] for row in parser.rows]

