        self.contexts = []
        self.skip_depth = 0

    def _ctx(self):
        if not self.contexts:
            self.contexts.append({'row': None, 'cell': None})
        return self.contexts[-1]

    def _close_cell(self, ctx):
        cell = ctx['cell']
        if cell is not None:
            kind, buf = cell
            if kind == 'td' and ctx['row'] is not None:
                ctx['row'].append(''.join(buf).strip())
            ctx['cell'] = None

    def _close_row(self, ctx):
        self._close_cell(ctx)
        ctx['row'] = None

    def _new_row(self, ctx):
        row = []
        self.rows.append(row)
        ctx['row'] = row

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if tag in ('script', 'style'):
            self.skip_depth += 1
            return
        if tag == 'table':
            self.contexts.append({'row': None, 'cell': None})
        elif tag == 'tr':
            ctx = self._ctx()
            self._close_row(ctx)
            self._new_row(ctx)
        elif tag in ('td', 'th'):
            ctx = self._ctx()
            self._close_cell(ctx)
            if ctx['row'] is None:
                self._new_row(ctx)
            ctx['cell'] = (tag, [])
        elif tag in ('thead', 'tbody', 'tfoot'):
            if self.contexts:
                self._close_row(self.contexts[-1])

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)

    def handle_endtag(self, tag):
        tag = tag.lower()
        if tag in ('script', 'style'):
            if self.skip_depth:
                self.skip_depth -= 1
            return
        if not self.contexts:
            return
        ctx = self.contexts[-1]
        if tag in ('td', 'th'):
            self._close_cell(ctx)
        elif tag == 'tr':
            self._close_row(ctx)
        elif tag in ('thead', 'tbody', 'tfoot'):
            self._close_row(ctx)
        elif tag == 'table':
            self._close_row(ctx)
            self.contexts.pop()

    def handle_data(self, data):
        if self.skip_depth:
            return
        for ctx in self.contexts:
            if ctx['cell'] is not None:
                ctx['cell'][1].append(data)

    def finish(self):
        self.close()
        while self.contexts:
            ctx = self.contexts.pop()
            self._close_row(ctx)
        return self.rows


