import math
import numbers
from decimal import Decimal
from fractions import Fraction


def _to_fraction(v, name):
    if isinstance(v, bool) or not isinstance(v, (numbers.Real, Decimal)):
        raise TypeError("Column %r contains non-numeric value %r" % (name, v))
    try:
        if isinstance(v, float) and not math.isfinite(v):
            raise ValueError
        return Fraction(v)
    except (ValueError, OverflowError, TypeError):
        raise ValueError("Column %r contains non-finite value %r" % (name, v))


def most_correlated_columns(data):
    if not isinstance(data, dict) or not data:
        raise ValueError("No data provided")
    if len(data) < 2:
        raise ValueError("At least two columns are required")
    names = list(data.keys())
    cols = []
    for name in names:
        col = data[name]
        if isinstance(col, (str, bytes)):
            raise TypeError("Column %r is not a sequence of numbers" % (name,))
        try:
            values = list(col)
        except TypeError:
            raise TypeError("Column %r is not a sequence of numbers" % (name,))
        cols.append(values)
    # type check before anything else
    for name, values in zip(names, cols):
        for v in values:
            if isinstance(v, bool) or not isinstance(v, (numbers.Real, Decimal)):
                raise TypeError("Column %r contains non-numeric value %r" % (name, v))
    n = len(cols[0])
    if any(len(c) != n for c in cols):
        raise ValueError("All columns must have the same length")
    if n == 0:
        raise ValueError("No data provided")
    fcols = [[_to_fraction(v, name) for v in values] for name, values in zip(names, cols)]
    sums = [sum(c, Fraction(0)) for c in fcols]
    sqs = [sum((x * x for x in c), Fraction(0)) for c in fcols]
    vars_ = [n * sq - s * s for s, sq in zip(sums, sqs)]
    best = None
    best_val = None
    k = len(names)
    for i in range(k):
        for j in range(i + 1, k):
            if vars_[i] == 0 or vars_[j] == 0:
                r2 = Fraction(0)
            else:
                sxy = sum((a * b for a, b in zip(fcols[i], fcols[j])), Fraction(0))
                cov = n * sxy - sums[i] * sums[j]
                r2 = (cov * cov) / (vars_[i] * vars_[j])
            if best_val is None or r2 > best_val:
                best_val = r2
                best = (names[i], names[j])
    return best

