import math
import numbers


def _validate_column(name, values):
    try:
        vals = list(values)
    except TypeError:
        raise TypeError(f"Column {name!r} is not a sequence of numbers")
    for v in vals:
        if isinstance(v, bool) or not isinstance(v, numbers.Real):
            raise TypeError(f"Column {name!r} contains non-numeric value {v!r}")
    return [float(v) for v in vals]


def _pearson(x, y):
    n = len(x)
    mx = math.fsum(x) / n
    my = math.fsum(y) / n
    dx = [a - mx for a in x]
    dy = [b - my for b in y]
    sxy = math.fsum(a * b for a, b in zip(dx, dy))
    sxx = math.fsum(a * a for a in dx)
    syy = math.fsum(b * b for b in dy)
    denom = math.sqrt(sxx) * math.sqrt(syy)
    if not denom or math.isnan(denom) or math.isinf(denom):
        return float('nan')
    r = sxy / denom
    if math.isnan(r):
        return r
    return max(-1.0, min(1.0, r))


def most_correlated_columns(data):
    if not isinstance(data, dict):
        raise TypeError("data must be a dict mapping column names to lists of numbers")
    if not data:
        raise ValueError("No data provided")
    if len(data) < 2:
        raise ValueError("At least two columns are required")

    names = list(data.keys())
    columns = [_validate_column(name, data[name]) for name in names]

    lengths = {len(c) for c in columns}
    if len(lengths) != 1:
        raise ValueError("All columns must have the same length")
    n = lengths.pop()
    if n == 0:
        raise ValueError("No data provided")
    if n < 2:
        raise ValueError("At least two rows are required to compute correlation")

    best_pair = None
    best_val = -1.0
    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            r = _pearson(columns[i], columns[j])
            if math.isnan(r):
                continue
            a = abs(r)
            if a > best_val:
                best_val = a
                best_pair = (names[i], names[j])

    if best_pair is None:
        # All correlations undefined (e.g. constant columns); fall back to first pair
        best_pair = (names[0], names[1])
    return best_pair

import numpy as np


def fft_magnitudes_of_row_sums(rows):
    rows = list(rows)
    if len(rows) == 0:
        return []
    arr = np.asarray(rows, dtype=float)
    if arr.ndim == 1:
        # Rows with zero columns, or a degenerate shape
        if arr.size == 0:
            sums = np.zeros(len(rows), dtype=float)
        else:
            sums = np.array([float(np.sum(np.asarray(r, dtype=float))) for r in rows])
    else:
        sums = arr.reshape(arr.shape[0], -1).sum(axis=1)
    coeffs = np.fft.fft(sums)
    return [float(x) for x in np.abs(coeffs)]

