def kmeans_clusters(xs, ys, n_clusters):
    xs = list(xs)
    ys = list(ys)
    if len(xs) != len(ys):
        raise ValueError("xs and ys must have the same length")
    n = len(xs)
    if isinstance(n_clusters, bool) or int(n_clusters) != n_clusters or n_clusters < 1:
        raise ValueError("n_clusters must be a positive integer")
    if n == 0:
        return []
    k = min(int(n_clusters), n)
    pts = [(float(x), float(y)) for x, y in zip(xs, ys)]

    def d2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def init_centers(start):
        centers = [pts[start]]
        mind = [d2(p, pts[start]) for p in pts]
        while len(centers) < k:
            best_i = 0
            best_d = -1.0
            for i in range(n):
                if mind[i] > best_d:
                    best_d = mind[i]
                    best_i = i
            c = pts[best_i]
            centers.append(c)
            for i in range(n):
                dd = d2(pts[i], c)
                if dd < mind[i]:
                    mind[i] = dd
        return centers

    def assign(centers):
        labels = []
        for p in pts:
            bj = 0
            bd = d2(p, centers[0])
            for j in range(1, k):
                dd = d2(p, centers[j])
                if dd < bd:
                    bd = dd
                    bj = j
            labels.append(bj)
        return labels

    def fix_empty(labels, centers):
        while True:
            sizes = [0] * k
            for l in labels:
                sizes[l] += 1
            empty = [j for j in range(k) if sizes[j] == 0]
            if not empty:
                return labels
            e = empty[0]
            best_i = -1
            best_d = -1.0
            for i in range(n):
                if sizes[labels[i]] > 1:
                    dd = d2(pts[i], centers[labels[i]])
                    if dd > best_d:
                        best_d = dd
                        best_i = i
            labels[best_i] = e
            centers[e] = pts[best_i]

    def centroids(labels):
        sx = [0.0] * k
        sy = [0.0] * k
        cnt = [0] * k
        for i, l in enumerate(labels):
            sx[l] += pts[i][0]
            sy[l] += pts[i][1]
            cnt[l] += 1
        return [(sx[j] / cnt[j], sy[j] / cnt[j]) if cnt[j] else (0.0, 0.0) for j in range(k)]

    def run(start):
        centers = init_centers(start)
        labels = None
        for _ in range(300):
            new_labels = assign(centers)
            new_labels = fix_empty(new_labels, list(centers))
            if new_labels == labels:
                break
            labels = new_labels
            centers = centroids(labels)
        inertia = sum(d2(pts[i], centers[labels[i]]) for i in range(n))
        return inertia, labels

    if n <= 20:
        starts = list(range(n))
    else:
        starts = sorted(set(int(i * n / 20) for i in range(20)))

    best = None
    for s in starts:
        inertia, labels = run(s)
        if best is None or inertia < best[0] - 1e-12:
            best = (inertia, labels)

    labels = best[1]
    groups = {}
    for i, l in enumerate(labels):
        groups.setdefault(l, []).append(i)
    clusters = [sorted(g) for g in groups.values() if g]
    clusters.sort(key=lambda c: c[0])
    return clusters

