import random


def _sqdist(p, q):
    dx = p[0] - q[0]
    dy = p[1] - q[1]
    return dx * dx + dy * dy


def _lloyd(points, centers, max_iter=300):
    n = len(points)
    k = len(centers)
    centers = [tuple(c) for c in centers]
    labels = None
    for _ in range(max_iter):
        new_labels = []
        for p in points:
            best_j = 0
            best_d = _sqdist(p, centers[0])
            for j in range(1, k):
                d = _sqdist(p, centers[j])
                if d < best_d:
                    best_d = d
                    best_j = j
            new_labels.append(best_j)
        # fix empty clusters
        counts = [0] * k
        for l in new_labels:
            counts[l] += 1
        for j in range(k):
            if counts[j] == 0:
                best_i = -1
                best_d = -1.0
                for i in range(n):
                    if counts[new_labels[i]] > 1:
                        d = _sqdist(points[i], centers[new_labels[i]])
                        if d > best_d:
                            best_d = d
                            best_i = i
                if best_i >= 0:
                    counts[new_labels[best_i]] -= 1
                    new_labels[best_i] = j
                    counts[j] = 1
        # recompute centers
        sx = [0.0] * k
        sy = [0.0] * k
        for i, l in enumerate(new_labels):
            sx[l] += points[i][0]
            sy[l] += points[i][1]
        new_centers = []
        for j in range(k):
            if counts[j] > 0:
                new_centers.append((sx[j] / counts[j], sy[j] / counts[j]))
            else:
                new_centers.append(centers[j])
        centers = new_centers
        if new_labels == labels:
            break
        labels = new_labels
    inertia = sum(_sqdist(points[i], centers[labels[i]]) for i in range(n))
    return inertia, labels


def _farthest_init(points, k, start):
    centers = [points[start]]
    mind = [_sqdist(p, points[start]) for p in points]
    while len(centers) < k:
        idx = max(range(len(points)), key=lambda i: mind[i])
        c = points[idx]
        centers.append(c)
        for i, p in enumerate(points):
            d = _sqdist(p, c)
            if d < mind[i]:
                mind[i] = d
    return centers


def _kpp_init(points, k, rng):
    n = len(points)
    centers = [points[rng.randrange(n)]]
    mind = [_sqdist(p, centers[0]) for p in points]
    while len(centers) < k:
        total = sum(mind)
        if total <= 0:
            c = points[rng.randrange(n)]
        else:
            r = rng.random() * total
            acc = 0.0
            c = points[-1]
            for i in range(n):
                acc += mind[i]
                if acc >= r:
                    c = points[i]
                    break
        centers.append(c)
        for i, p in enumerate(points):
            d = _sqdist(p, c)
            if d < mind[i]:
                mind[i] = d
    return centers


