from fractions import Fraction


def classification_summary(y_true, y_pred):
    y_true = list(y_true)
    y_pred = list(y_pred)
    if len(y_true) != len(y_pred):
        raise ValueError("y_true and y_pred must have the same length")
    n = len(y_true)

    seen = []
    seen_set = set()
    for lab in y_true + y_pred:
        if lab not in seen_set:
            seen_set.add(lab)
            seen.append(lab)
    try:
        labels = sorted(seen)
    except TypeError:
        labels = seen

    tp = {lab: 0 for lab in labels}
    true_cnt = {lab: 0 for lab in labels}
    pred_cnt = {lab: 0 for lab in labels}
    correct = 0
    for t, p in zip(y_true, y_pred):
        true_cnt[t] += 1
        pred_cnt[p] += 1
        if t == p:
            tp[t] += 1
            correct += 1

    report = {}
    exact = {}
    for lab in labels:
        prec = Fraction(tp[lab], pred_cnt[lab]) if pred_cnt[lab] else Fraction(0)
        rec = Fraction(tp[lab], true_cnt[lab]) if true_cnt[lab] else Fraction(0)
        f1 = (2 * prec * rec / (prec + rec)) if (prec + rec) != 0 else Fraction(0)
        exact[lab] = (prec, rec, f1, true_cnt[lab])
        report[lab] = (float(prec), float(rec), float(f1), true_cnt[lab])

    report['accuracy'] = float(Fraction(correct, n)) if n else 0.0

    k = len(labels)
    if k:
        mp = sum((exact[l][0] for l in labels), Fraction(0)) / k
        mr = sum((exact[l][1] for l in labels), Fraction(0)) / k
        mf = sum((exact[l][2] for l in labels), Fraction(0)) / k
    else:
        mp = mr = mf = Fraction(0)
    report['macro avg'] = (float(mp), float(mr), float(mf), n)

    total = sum(true_cnt.values())
    if total:
        wp = sum((exact[l][0] * exact[l][3] for l in labels), Fraction(0)) / total
        wr = sum((exact[l][1] * exact[l][3] for l in labels), Fraction(0)) / total
        wf = sum((exact[l][2] * exact[l][3] for l in labels), Fraction(0)) / total
    else:
        wp = wr = wf = Fraction(0)
    report['weighted avg'] = (float(wp), float(wr), float(wf), n)

    return report

