from datetime import datetime, timezone

try:
    from zoneinfo import ZoneInfo
except ImportError:  # Python < 3.9
    ZoneInfo = None

_FMT_IN = '%d/%m/%y %H:%M:%S.%f'
_FMT_OUT = '%d/%m/%y %H:%M:%S.%f'


def _localize(naive_dt, tz_name):
    """Attach timezone tz_name to a naive datetime, returning an aware datetime."""
    if ZoneInfo is not None:
        try:
            return naive_dt.replace(tzinfo=ZoneInfo(tz_name))
        except Exception:
            pass
    import pytz
    return pytz.timezone(tz_name).localize(naive_dt)


def _convert(aware_dt, tz_name):
    """Express an aware datetime in timezone tz_name."""
    if ZoneInfo is not None:
        try:
            return aware_dt.astimezone(ZoneInfo(tz_name))
        except Exception:
            pass
    import pytz
    tz = pytz.timezone(tz_name)
    return tz.normalize(aware_dt.astimezone(tz))


def convert_time_between_zones(time_string, from_tz, to_tz):
    naive = datetime.strptime(time_string.strip(), _FMT_IN)
    aware = _localize(naive, from_tz)
    utc_dt = aware.astimezone(timezone.utc)
    result = _convert(utc_dt, to_tz)
    return result.strftime(_FMT_OUT)

