import math
from collections import Counter

_URL_RE = re.compile(r'https?://\S+')
_TOKEN_RE = re.compile(r'\w{2,}')


def _tokenize(text):
    if not text:
        return []
    cleaned = _URL_RE.sub(' ', text)
    return [t.lower() for t in _TOKEN_RE.findall(cleaned)]


def tfidf_without_urls(texts):
    texts = list(texts) if texts is not None else []
    tokenized = [_tokenize(t) for t in texts]
    counts = [Counter(toks) for toks in tokenized]
    vocab = sorted(set().union(*counts)) if counts else []
    if not vocab:
        return ([], [])
    n = len(texts)
    df = Counter()
    for c in counts:
        df.update(c.keys())
    idf = {w: math.log((1 + n) / (1 + df[w])) + 1 for w in vocab}
    rows = []
    for c in counts:
        row = [c.get(w, 0) * idf[w] for w in vocab]
        norm = math.sqrt(sum(v * v for v in row))
        if norm > 0:
            row = [v / norm for v in row]
        else:
            row = [0.0 for _ in row]
        rows.append(row)
    return (rows, vocab)

