import math
import re

_GROUPED = re.compile(r'^[+-]?\d{1,3}(?:,\d{3})+(?:\.\d*)?(?:[eE][+-]?\d+)?$')


def _parse_number(s):
    if s is None:
        return None
    s = s.strip()
    if not s:
        return None
    if ',' in s:
        if not _GROUPED.match(s):
            return None
        s = s.replace(',', '')
    try:
        v = float(s)
    except ValueError:
        return None
    if not math.isfinite(v):
        return None
    return v


def summarize_numeric_csv(csv_text):
    if csv_text.startswith('\ufeff'):
        csv_text = csv_text[1:]
    reader = csv.reader(io.StringIO(csv_text))
    rows = list(reader)
    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}
    header = rows[0]
    data = [r for r in rows[1:] if any(c.strip() for c in r)]
    columns = {}
    order = []
    for idx, name in enumerate(header):
        values = []
        ok = True
        for r in data:
            v = _parse_number(r[idx]) if idx < len(r) else None
            if v is None:
                ok = False
                break
            values.append(v)
        if ok and values:
            if name not in columns:
                order.append(name)
            columns[name] = values
    means = {}
    std_devs = {}
    for name in order:
        vals = columns[name]
        n = len(vals)
        m = math.fsum(vals) / n
        means[name] = m
        if n >= 2:
            ss = math.fsum((x - m) ** 2 for x in vals)
            std_devs[name] = math.sqrt(ss / (n - 1))
        else:
            std_devs[name] = None
    f_value = None
    k = len(order)
    if k >= 2:
        all_vals = [x for name in order for x in columns[name]]
        N = len(all_vals)
        df_b = k - 1
        df_w = N - k
        if df_w > 0:
            grand = math.fsum(all_vals) / N
            ssb = math.fsum(len(columns[n_]) * (means[n_] - grand) ** 2 for n_ in order)
            ssw = math.fsum((x - means[n_]) ** 2 for n_ in order for x in columns[n_])
            if ssw == 0:
                f_value = float('inf') if ssb > 0 else float('nan')
            else:
                f_value = (ssb / df_b) / (ssw / df_w)
    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}

