import math

def standardize_columns(rows):
    if not rows:
        return []
    n = len(rows)
    ncols = len(rows[0])
    result = [[0.0] * ncols for _ in range(n)]
    for j in range(ncols):
        col = [float(r[j]) for r in rows]
        if max(col) == min(col):
            continue
        mean = math.fsum(col) / n
        var = math.fsum((x - mean) ** 2 for x in col) / n
        std = math.sqrt(var)
        if std == 0.0:
            continue
        for i in range(n):
            result[i][j] = (col[i] - mean) / std
    return result

