    selected = [name for name in files if fnmatch.fnmatchcase(name, name_pattern)]
    if not selected:
        raise ValueError('No file names match the pattern %r' % (name_pattern,))
    selected.sort(key=_natural_key)

    regex = re.compile(value_pattern) if not isinstance(value_pattern, re.Pattern) else value_pattern
    one_group = regex.groups == 1

    result = []
    for name in selected:
        content = files[name]
        if content is None:
            content = ''
        elif isinstance(content, bytes):
            content = content.decode('utf-8', errors='replace')
        matches = []
        for m in regex.finditer(content):
            if one_group:
                g = m.group(1)
                matches.append(g if g is not None else '')
            else:
                matches.append(m.group(0))
        result.append((name, matches))
