import csv
import io
import re

_INT_RE = re.compile(r'^[+-]?\d+$')
_FLOAT_RE = re.compile(r'^[+-]?(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?$')


def _parse_document(text):
    if text.startswith('\ufeff'):
        text = text[1:]
    reader = csv.reader(io.StringIO(text, newline=''))
    header = None
    rows = []
    for row in reader:
        if header is None:
            if not row or all(c.strip() == '' for c in row):
                continue
            header = [c.strip() for c in row]
            continue
        if not row:
            continue
        rows.append(row)
    return header, rows


def concat_csv_tables(csv_texts):
    if csv_texts is None:
        raise ValueError('No CSV documents provided')
    csv_texts = list(csv_texts)
    if not csv_texts:
        raise ValueError('No CSV documents provided')

    columns = None
    records = []
    for text in csv_texts:
        if text is None:
            continue
        header, rows = _parse_document(text)
        if header is None:
            continue
        if columns is None:
            columns = list(header)
        for row in rows:
            rec = {}
            for i, name in enumerate(header):
                rec[name] = row[i] if i < len(row) else ''
            records.append({c: rec.get(c, '') for c in columns})

    if columns is None:
        return []

    for col in columns:
        values = [r[col].strip() for r in records]
        non_empty = [v for v in values if v != '']
        if not non_empty:
            continue
        if all(_INT_RE.match(v) for v in non_empty):
            conv = int
        elif all(_INT_RE.match(v) or _FLOAT_RE.match(v) for v in non_empty):
            conv = float
        else:
            continue
        for r, v in zip(records, values):
            r[col] = conv(v) if v != '' else None

    return records

