import csv
import io
import math
import re

_INT_RE = re.compile(r'^\s*[+-]?\d+\s*$')


def _is_missing(v):
    return v is None or (isinstance(v, str) and v.strip() == '')


def _is_int(s):
    return bool(_INT_RE.match(s))


def _is_float(s):
    if '_' in s:
        return False
    try:
        float(s)
        return True
    except (ValueError, TypeError):
        return False


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must be a non-empty list")

    columns = None
    rows = []
    for text in csv_texts:
        reader = csv.reader(io.StringIO(text))
        header = None
        for record in reader:
            if header is None:
                if not record:
                    continue
                header = record
                if columns is None:
                    columns = list(header)
                continue
            if not record:
                continue
            row = {}
            for i, name in enumerate(header):
                row[name] = record[i] if i < len(record) else None
            rows.append(row)

    if columns is None:
        return []

    # Determine column types
    converters = {}
    for col in columns:
        values = [r.get(col) for r in rows]
        present = [v for v in values if not _is_missing(v)]
        has_missing = len(present) != len(values)
        if present and all(_is_int(v) for v in present):
            if has_missing:
                converters[col] = lambda v: float('nan') if _is_missing(v) else float(int(v))
            else:
                converters[col] = lambda v: int(v)
        elif present and all(_is_float(v) for v in present):
            converters[col] = lambda v: float('nan') if _is_missing(v) else float(v)
        else:
            converters[col] = lambda v: '' if v is None else v

    result = []
    for r in rows:
        result.append({col: converters[col](r.get(col)) for col in columns})
    return result

