        r += 1
    x = [0] * n
    for i, c in enumerate(pivots):
        x[c] = M[i][n]
    return x


def _fit(X, y, conv, exact):
    n = len(y)
    k = len(X[0]) if X else 0
    X = [[conv(v) for v in row] for row in X]
    y = [conv(v) for v in y]
    ym = sum(y) / n
    xm = [sum(X[i][j] for i in range(n)) / n for j in range(k)]
    Xc = [[X[i][j] - xm[j] for j in range(k)] for i in range(n)]
    yc = [v - ym for v in y]
    A = [[sum(Xc[i][a] * Xc[i][b] for i in range(n)) for b in range(k)] for a in range(k)]
    rhs = [sum(Xc[i][a] * yc[i] for i in range(n)) for a in range(k)]
    if exact:
        tol = 0
    else:
        scale = max([abs(A[i][i]) for i in range(k)] + [0.0])
        tol = 1e-12 * scale if scale > 0 else 0.0
    coef = _solve(A, rhs, tol) if k else []
    intercept = ym - sum(c * m for c, m in zip(coef, xm))
    return [float(c) for c in coef], float(intercept)


def column_linear_regression(rows, columns, target):
    if not rows:
        raise ValueError("rows must not be empty")
    columns = list(columns)
    if target not in columns:
        raise ValueError("target is not one of the columns")
    t = columns.index(target)
    m = len(columns)
    X = []
    y = []
    for row in rows:
        row = list(row)
        if len(row) != m:
            raise ValueError("row length does not match number of columns")
        y.append(row[t])
        X.append([row[j] for j in range(m) if j != t])
    try:
        return _fit(X, y, Fraction, True)
    except (TypeError, ValueError, OverflowError):
        return _fit(X, y, float, False)

