import math


def _solve_exact(A, b):
    n = len(A)
    M = [list(A[i]) + [b[i]] for i in range(n)]
    for col in range(n):
        piv = None
        for r in range(col, n):
            if M[r][col] != 0:
                piv = r
                break
        if piv is None:
            return None
        M[col], M[piv] = M[piv], M[col]
        pv = M[col][col]
        for r in range(n):
            if r != col and M[r][col] != 0:
                f = M[r][col] / pv
                rowc = M[col]
                rr = M[r]
                for c in range(col, n + 1):
                    rr[c] -= f * rowc[c]
    return [M[i][n] / M[i][i] for i in range(n)]


