import re
import math
from collections import Counter


def _normalise(text):
    return re.sub(r'[\W_]+', ' ', text.lower())


def _lcs_length(a, b):
    if len(a) < len(b):
        a, b = b, a
    if not b:
        return 0
    prev = [0] * (len(b) + 1)
    for ca in a:
        cur = [0] * (len(b) + 1)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                cur[j] = prev[j - 1] + 1
            else:
                cur[j] = cur[j - 1] if cur[j - 1] > prev[j] else prev[j]
        prev = cur
    return prev[-1]


def text_similarity_scores(text1, text2):
    n1 = _normalise(text1)
    n2 = _normalise(text2)

    c1 = Counter(n1.split())
    c2 = Counter(n2.split())
    if not c1 or not c2:
        cosine = 0.0
    else:
        dot = sum(v * c2[k] for k, v in c1.items() if k in c2)
        norm1 = math.sqrt(sum(v * v for v in c1.values()))
        norm2 = math.sqrt(sum(v * v for v in c2.values()))
        cosine = float(dot) / (norm1 * norm2)

    total = len(n1) + len(n2)
    if total == 0:
        ratio = 1.0
    else:
        lcs = _lcs_length(n1, n2)
        ratio = 2.0 * lcs / total

    return (cosine, ratio)

