import re
import math
from collections import Counter

try:
    from rapidfuzz.distance import Indel as _Indel
except Exception:  # pragma: no cover
    _Indel = None

_NON_ALNUM = re.compile(r'[\W_]+')


def _normalise(text):
    return _NON_ALNUM.sub(' ', text.lower())


def _lcs_len(a, b):
    # Bit-parallel LCS length (Hyyro / Allison-Dix)
    if not a or not b:
        return 0
    n = len(a)
    masks = {}
    for i, ch in enumerate(a):
        masks[ch] = masks.get(ch, 0) | (1 << i)
    full = (1 << n) - 1
    S = full
    for ch in b:
        M = masks.get(ch, 0)
        U = S & M
        S = ((S + U) | (S - U)) & full
    return n - bin(S).count('1')


def _indel_ratio(a, b):
    total = len(a) + len(b)
    if total == 0:
        return 1.0
    if _Indel is not None:
        return float(_Indel.normalized_similarity(a, b))
    dist = total - 2 * _lcs_len(a, b)
    return 1.0 - dist / total


def _cosine(a, b):
    ca = Counter(a.split())
    cb = Counter(b.split())
    if not ca or not cb:
        return 0.0
    dot = sum(v * cb[k] for k, v in ca.items() if k in cb)
    na = math.sqrt(sum(v * v for v in ca.values()))
    nb = math.sqrt(sum(v * v for v in cb.values()))
    if na == 0 or nb == 0:
        return 0.0
    return dot / (na * nb)


def text_similarity_scores(text1, text2):
    n1 = _normalise(text1)
    n2 = _normalise(text2)
    return (float(_cosine(n1, n2)), float(_indel_ratio(n1, n2)))

