import math


def complete_row_histogram(data, bins):
    if isinstance(bins, bool) or not isinstance(bins, int) or bins < 1:
        raise ValueError("bins must be a positive integer")
    columns = list(data.keys())
    lengths = {len(data[c]) for c in columns}
    if len(lengths) > 1:
        raise ValueError("all columns must have the same length")
    n = lengths.pop() if lengths else 0

    cleaned = {c: [] for c in columns}
    for i in range(n):
        row = [data[c][i] for c in columns]
        if any(v is None for v in row):
            continue
        for c, v in zip(columns, row):
            cleaned[c].append(float(v))

    pooled = [v for c in columns for v in cleaned[c]]
    if not pooled:
        return cleaned, None
    lo = min(pooled)
    hi = max(pooled)
    if lo == hi or not (math.isfinite(lo) and math.isfinite(hi)):
        return cleaned, None

    width = hi - lo
    edges = [lo + width * i / bins for i in range(bins + 1)]
    edges[-1] = hi
    counts = [0] * bins
    for x in pooled:
        idx = int((x - lo) / width * bins)
        if idx >= bins:
            idx = bins - 1
        elif idx < 0:
            idx = 0
        # correct for floating-point rounding against the actual edges
        if idx > 0 and x < edges[idx]:
            idx -= 1
        elif idx < bins - 1 and x >= edges[idx + 1]:
            idx += 1
        counts[idx] += 1
    return cleaned, counts

