import csv
import io
import math
import re

_THOUSANDS_RE = re.compile(r'^[+-]?\d{1,3}(?:,\d{3})+(?:\.\d*)?$')


def _parse_number(s):
    if s is None:
        return None
    s = s.strip()
    if not s:
        return None
    if ',' in s:
        if not _THOUSANDS_RE.match(s):
            return None
        s = s.replace(',', '')
    try:
        v = float(s)
    except ValueError:
        return None
    if not math.isfinite(v):
        return None
    return v


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = [r for r in reader if r and any(c.strip() for c in r)]
    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}
    header = [h.strip() for h in rows[0]]
    data = rows[1:]
    columns = {}
    order = []
    for idx, name in enumerate(header):
        values = []
        ok = True
        for r in data:
            if idx >= len(r):
                ok = False
                break
            v = _parse_number(r[idx])
            if v is None:
                ok = False
                break
            values.append(v)
        if ok and values:
            if name not in columns:
                order.append(name)
            columns[name] = values
    means = {}
    std_devs = {}
    for name in order:
        vals = columns[name]
        n = len(vals)
        m = math.fsum(vals) / n
        means[name] = m
        if n >= 2:
            ss = math.fsum((x - m) ** 2 for x in vals)
            std_devs[name] = math.sqrt(ss / (n - 1))
        else:
            std_devs[name] = None
    f_value = None
    k = len(order)
    if k >= 2:
        total_n = sum(len(columns[n]) for n in order)
        grand = math.fsum(math.fsum(columns[n]) for n in order) / total_n
        ssb = math.fsum(len(columns[n]) * (means[n] - grand) ** 2 for n in order)
        ssw = math.fsum(math.fsum((x - means[n]) ** 2 for x in columns[n]) for n in order)
        df_b = k - 1
        df_w = total_n - k
        if df_w <= 0:
            f_value = None
        elif ssw == 0:
            f_value = float('inf') if ssb > 0 else float('nan')
        else:
            f_value = (ssb / df_b) / (ssw / df_w)
    return {'means': means, 'std_devs': std_devs, 'f_value': f_value}

