import csv
import io
import math


def _parse_number(s):
    if s is None:
        return None
    t = s.strip().replace(',', '').replace('_', '#')
    if not t:
        return None
    try:
        v = float(t)
    except ValueError:
        return None
    if not math.isfinite(v):
        return None
    return v


def _mean(xs):
    return sum(xs) / len(xs)


def _sample_std(xs):
    n = len(xs)
    if n < 2:
        return float('nan')
    m = _mean(xs)
    return math.sqrt(sum((x - m) ** 2 for x in xs) / (n - 1))


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))
    rows = [r for r in reader if r and any(c.strip() for c in r)]
    if not rows:
        return {'means': {}, 'std_devs': {}, 'f_value': None}
    header = [h.strip() for h in rows[0]]
    data = rows[1:]

    numeric = {}
    for i, name in enumerate(header):
        vals = []
        ok = True
        for r in data:
            cell = r[i] if i < len(r) else None
            v = _parse_number(cell)
            if v is None:
                ok = False
                break
            vals.append(v)
        if ok and vals:
            numeric[name] = vals

    means = {k: _mean(v) for k, v in numeric.items()}
    stds = {k: _sample_std(v) for k, v in numeric.items()}

    f_value = None
    groups = list(numeric.values())
    k = len(groups)
    if k >= 2:
        N = sum(len(g) for g in groups)
        grand = sum(sum(g) for g in groups) / N
        ssb = sum(len(g) * (_mean(g) - grand) ** 2 for g in groups)
        ssw = sum(sum((x - _mean(g)) ** 2 for x in g) for g in groups)
        df_b = k - 1
        df_w = N - k
        if df_w <= 0:
            f_value = float('nan')
        else:
            msb = ssb / df_b
            msw = ssw / df_w
            if msw == 0:
                f_value = float('inf') if msb > 0 else float('nan')
            else:
                f_value = msb / msw

    return {'means': means, 'std_devs': stds, 'f_value': f_value}
